    FontClip(Clip.load(asset("clips/clip92/clip.acpk")),
             FontClip.loadCharmap(charmap()), 4)

fun world(charmap: ByteArray? = null, aj: Int = 0):
    Level0World {
    Entity.grabLatch = false                      // static latch — reset per world
    Entity.gq = false                             // g.q wall-run latch
    Entity.gf = null                              // g.f marker FX ref
    Entity.gE = false                             // g.E jump-tail suppress
    Entity.icu = false                            // i.cu static
    // mirror of the game's conversion of decoded assets
    val level = LevelPack.load(asset("level$aj/level$aj.aclv"))
        val clips = mutableMapOf(
            0 to Clip.load(asset("clips/clip0/clip.acpk")),
            1 to Clip.load(asset("clips/clip1/clip.acpk")),
            3 to Clip.load(asset("clips/clip3/clip.acpk")),
            7 to Clip.load(asset("clips/clip7/clip.acpk")),
            9 to Clip.load(asset("clips/clip9/clip.acpk")),
            32 to Clip.load(asset("clips/clip32/clip.acpk")),
            54 to Clip.load(asset("clips/clip54/clip.acpk")),
            64 to Clip.load(asset("clips/clip64/clip.acpk")),
            26 to Clip.load(asset("clips/clip26/clip.acpk")),
            27 to Clip.load(asset("clips/clip27/clip.acpk")),
            35 to Clip.load(asset("clips/clip35/clip.acpk")),
            10 to Clip.load(asset("clips/clip10/clip.acpk")),
            48 to Clip.load(asset("clips/clip48/clip.acpk")),
            45 to Clip.load(asset("clips/clip45/clip.acpk")),
            47 to Clip.load(asset("clips/clip47/clip.acpk")),
            31 to Clip.load(asset("clips/clip31/clip.acpk")),
            4 to Clip.load(asset("clips/clip4/clip.acpk")),
            11 to Clip.load(asset("clips/clip11/clip.acpk")),
            62 to Clip.load(asset("clips/clip62/clip.acpk")),
            25 to Clip.load(asset("clips/clip25/clip.acpk")),
            29 to Clip.load(asset("clips/clip29/clip.acpk")),
            60 to Clip.load(asset("clips/clip60/clip.acpk")),
            51 to Clip.load(asset("clips/clip51/clip.acpk")),
            63 to Clip.load(asset("clips/clip63/clip.acpk")),
            19 to Clip.load(asset("clips/clip19/clip.acpk")),
            36 to Clip.load(asset("clips/clip36/clip.acpk")),
            40 to Clip.load(asset("clips/clip40/clip.acpk")),
            20 to Clip.load(asset("clips/clip20/clip.acpk")),
            21 to Clip.load(asset("clips/clip21/clip.acpk")),
            38 to Clip.load(asset("clips/clip38/clip.acpk")),
            42 to Clip.load(asset("clips/clip42/clip.acpk")),
            46 to Clip.load(asset("clips/clip46/clip.acpk")),
            92 to Clip.load(asset("clips/clip92/clip.acpk")),
            14 to Clip.load(asset("clips/clip14/clip.acpk")),   // bi[22] ax22 zone
            15 to Clip.load(asset("clips/clip15/clip.acpk")),   // bi[26] glider
            16 to Clip.load(asset("clips/clip16/clip.acpk")),   // bi[25] ax25 player
            12 to Clip.load(asset("clips/clip94/clip.acpk")),   // z[12] = entry-012
            23 to Clip.load(asset("clips/clip23/clip.acpk")),   // ax66 platforms (bi[66]=23)
            61 to Clip.load(asset("clips/clip61/clip.acpk")),   // ax13 ropes (bi[13]=61)
            6 to Clip.load(asset("clips/clip6/clip.acpk")),     // ax10 zones (bi[10]=6, zero-pixel)
            28 to Clip.load(asset("clips/clip28/clip.acpk")),   // ax51 crates (bi[51]=28)
            44 to Clip.load(asset("clips/clip44/clip.acpk")),   // ax31 (bi[31]=44)
            13 to Clip.load(asset("clips/clip13/clip.acpk")),   // ax21 director + ax48 child (bi=13)
            52 to Clip.load(asset("clips/clip52/clip.acpk")),   // ax29 boss (bi[29]=52)
            30 to Clip.load(asset("clips/clip30/clip.acpk")),   // ax41 knockable (bi[41]=30)
            71 to Clip.load(asset("clips/clip71/clip.acpk")),   // ax61 multi-tool (bi[61]=71)
        )
        if (aj == 0) {
            clips[-10] = Clip.load(asset("level0/tileset-10/clip.acpk"))
            clips[-11] = Clip.load(asset("level0/tileset-11/clip.acpk"))
            clips[-12] = Clip.load(asset("level0/tileset-12/clip.acpk"))
        }
    // pack-14 entry-<aj+1> level-string table (line-delimited emit)
    // j.g(i) slot fidelity (same fix as the gdx loader, k.d→j.g): empty
    // pack slots are real table entries — filtering shifts every later
    // index (slice-316 root cause of the invisible bubbles).
    val levelStrings = java.io.File("../generated/level$aj/strings-${aj + 1}.txt")
        .readText().split("\n")
        .let { if (it.last().isEmpty()) it.dropLast(1) else it }
        .map { it.replace("\\n", "\n") }
    return Level0World(level, clips, DeterministicRandom(1L),
        levelStrings = levelStrings, charmap = charmap,
        scripts = ScriptTables.load(asset("level$aj/scripts.bin")),
        aj = aj, packLoader = { a -> missionPackFor(a) })
        .also {
            // the intro claim script's op105 dialogs (k.l(21)) suspend the
            // sim until a dismiss press — emulate an instantly-tapping player
            it.autoDismissDialog = true
        }
}

/** `I(aj)` provider for tests — the same `level<aj>` asset triplet the
 *  gdx launcher assembles in `missionPack`. */
private fun missionPackFor(aj: Int): MissionPack {
    val strings = java.io.File("../generated/level$aj/strings-${aj + 1}.txt")
        .readText().split("\n")
        .let { if (it.last().isEmpty()) it.dropLast(1) else it }
        .map { it.replace("\\n", "\n") }
    return MissionPack(
        LevelPack.load(asset("level$aj/level$aj.aclv")), strings,
        ScriptTables.load(asset("level$aj/scripts.bin")))
}

/** `P|16` — the director's keep-live flag: the `k.I()` eligibility gate
 *  (k.java L25f/L26d) ticks the entity even when `au>=2` off-camera.
 *  Tests pin it on entities they exercise directly so the verbatim
 *  au/park gate doesn't freeze them while the camera sits at spawn —
 *  the same mechanism the original claim scripts use to keep actors live. */
private fun keepLive(e: Entity) { e.P = e.P or 16 }

/** Teleport the player onto an ax2 checkpoint record and arm the
 *  entity's `P|16` force-tick so its `aY()` arm runs this tick —
 *  without it, the `k.I()` au/park gate freezes the checkpoint until
 *  the (unmoved) camera arrives (k.java L25f eligibility). In real
 *  play the camera delivers the same tick on approach. */
private fun overlapCheckpoint(w: Level0World, cp: Level0World.Checkpoint) {
    w.player.setPositionPx(cp.ak, cp.al + 5)
    w.npcs.firstOrNull { it.ax == 2 && it.aw == cp.aw }?.let(::keepLive)
}

fun settleIntro(w: Level0World) {
    // the spawn-intro claim script binds `k.C` in phases (~70 ticks each)
    // even with auto-dismiss dialogs; the `I()` L108 gate suspends
    // non-exempt entities while a claim is `ab()`. Fast-forward until the
    // claim stays released so tests see the post-intro play state they
    // were written against.
    var t = 0; var quiet = 0
    while (t++ < 400 && quiet < 40) {
        w.tick(emptyList())
        quiet = if (w.kC == null) quiet + 1 else 0
    }
}

/** L777's `!h(ak/20,al/20) && !h(ak/20,al/20+1) && s==null → i(25)`
 *  fall arm (i.java:6219) — drop spawned entities onto real ground the
 *  way the original's record placement does, else test subjects
 *  suspended mid-air correctly fall into S25. */
private fun standOn(w: Level0World, e: Entity) {
    val cx = e.ak / 20
    if (w.collisionCell(cx, e.al / 20) >= 5 ||
        w.collisionCell(cx, e.al / 20 + 1) >= 5) return
    var cy = e.al / 20 + 1
    while (cy < w.level.worldH / 20 + 4) {
        if (w.collisionCell(cx, cy) >= 5) {
            e.al = cy * 20 - 1; e.O = e.al shl 8; e.refreshBoxes(); return
        }
        cy++
    }
}

class Level0WorldTest {

    @Test fun `level decodes pack-6 shape`() {
        val w = world()
        assertEquals(627, w.level.cols)
        assertEquals(55, w.level.rows)
        assertEquals(637, w.level.entities.size)
        assertEquals(4, w.level.layers.size)
    }

    @Test fun `player spawns from a type-0 or 25 record`() {
        val w = world()
        assertNotNull(w.level.playerSpawn(), "level 0 must carry a spawn record")
    }

    @Test fun `collision out of bounds is solid sentinel 20`() {
        val w = world()
        assertEquals(20, w.level.collisionCell(-1, 0))
        assertEquals(20, w.level.collisionCell(0, -1))
        assertEquals(20, w.level.collisionCell(0, 55))
    }

    @Test fun `NPC family entities spawn at record positions`() {
        val w = world()
        assertTrue(w.npcs.isNotEmpty(), "expected clip-7 family entities")
        // record positions are authoritative — several records sit outside
        // the tile grid (ax9 at y=1106 > worldH=1100; ax74s at x>12540)
        // and the original spawns them unclamped.
        val byAw = w.level.entities.associate { it[1] to (it[2] to it[3]) }
        for (n in w.npcs) {
            val exp = byAw[n.aw]
            if (exp != null) {
                if (n.ax == 11 || n.ax == 73) {
                    // ctor tail `a(true);E()` (i.java:2895-2898) settles
                    // soldiers at spawn: collideSides pushes ak out of
                    // walls and E() sinks al in +10 steps to standable
                    // ground — both drift within a small window.
                    assertTrue(kotlin.math.abs(n.ak - exp.first) <= 10 &&
                        n.al >= exp.second && n.al <= exp.second + 40,
                        "ax${n.ax} aw=${n.aw} settled pos near (${exp.first},${exp.second}) got (${n.ak},${n.al})")
                } else {
                    assertEquals(exp, n.ak to n.al,
                        "ax${n.ax} aw=${n.aw} should sit at its record position")
                }
            }
        }
    }

    @Test fun `player falls with gravity and lands on solid ground`() {
        val w = world()
        // settle: run ticks until landing or timeout
        var ticks = 0
        while (w.player.ah != 0 && ticks++ < 600) w.tick(emptyList())
        assertEquals(0, w.player.ah, "player should have landed")
        val feetCell = w.level.collisionCell(w.player.ak / 20, (w.player.al + 1) / 20)
        // feet cell may be one row below the anchor depending on hitbox;
        // assert the *supporting* cell is solid or one-way
        val v1 = w.level.collisionAtPx(w.player.ak, w.player.al + 1)
        val v2 = w.level.collisionAtPx(w.player.ak, w.player.al + 21)
        assertTrue(w.level.isSolid(v1) || w.level.isOneWay(v1) ||
                   w.level.isSolid(v2) || w.level.isOneWay(v2) ||
                   w.level.isSolid(feetCell),
            "player should rest on ground (got $v1/$v2/$feetCell)")
    }

    @Test fun `long falls cannot tunnel through floors (terminal velocity 5120)`() {
        // g.java:578 (proven): ah capped at 5120 = 20px/tick = one cell,
        // which is what stops high-speed descents skipping a floor row.
        val w = world()
        val p = w.player
        // settle first so spawn X sits on real ground
        var t = 0
        while (p.ah != 0 && t++ < 600) w.tick(emptyList())
        val floorY = p.al
        // drop from 20 cells up in fall state S=43
        p.al = floorY - 20 * 20
        p.setAnim(43)
        t = 0
        while (p.ah != 0 && t++ < 600) w.tick(emptyList())
        assertTrue(p.al <= floorY + 21,
            "player tunneled through floor: al=${p.al} floor=$floorY")
    }

    @Test fun `hold-right runs the player forward`() {
        val w = world()
        // Start past the spawn-intro ax5 claim zone [49,863,116,941] —
        // now that the player carries its record uid (findByAw), the
        // first tap binds the claim and its script hijacks the run.
        w.player.setPositionPx(300, 940); w.player.refreshBoxes()
        val x0 = w.player.ak
        val q = InputQueue()
        // MR cell (cell5) -> mask 64 -> u(8256) held RIGHT (k.java:489)
        val (rx, ry) = w.cellPoint(5)
        q.post(InputQueue.Type.DOWN, rx, ry)
        repeat(30) { w.tick(q.drainTo(q.headSequence())) }
        assertTrue(w.player.ak > x0, "player should have moved right")
        // run cap ±2560 (proven literal from g.e()/ax())
        assertTrue(w.player.ag <= 2560)
    }

    @Test fun `player run uses clip0 anim 12 after run-start`() {
        val w = world()
        // settle so the press lands while grounded
        var t = 0
        while (w.player.ah != 0 && t++ < 600) w.tick(emptyList())
        // start past the spawn-intro ax5 claim zone [49,863,116,941] — else
        // the first tap binds it and velClampTail locks the run mid-vault.
        w.player.setPositionPx(300, 940)
        w.kM(2)
        val q = InputQueue()
        // hold RIGHT (MR cell5 → mask 64): the tap edge fires the proven
        // vault-jump (S233), and the aS-edge-bump in land() keeps aZ
        // correct after landing.
        val (rx, ry) = w.cellPoint(5)
        q.post(InputQueue.Type.DOWN, rx, ry)
        var seen = false
        repeat(200) {
            w.tick(q.drainTo(q.headSequence()))
            if (w.player.S == 12 || w.player.S == 32) seen = true
        }
        assertTrue(seen, "expected run anims 32/12 at some point, last S=${w.player.S}")
    }

    @Test fun `tap top third jumps through 21-22-23-43-5 landing chain`() {
        val w = world()
        val q = InputQueue()
        // settle first — the spawn-adjacent ax5 zone claims its intro
        // script here (k.C bound; aa() L341 zeros player velocity while
        // the script steps — the original's cutscene lock). Release it
        // and walk to open ground so the jump isn't script-locked or
        // support-variant S233.
        repeat(10) { w.tick(emptyList()) }
        w.kC?.releaseClaim(w); w.kC = null
        w.player.setPositionPx(600, w.player.al)
        // wait for the landing — x600 sits over a drop, and the jump tail
        // (`cq && v(action)`) only fires while an l()-family arm re-arms
        // cq this tick — i.e. the press must land while grounded.
        var grounded = false
        repeat(80) {
            w.tick(emptyList())
            if (w.player.aZ && w.player.S == 0) { grounded = true; return@repeat }
        }
        assertTrue(grounded, "player should settle grounded before the tap")
        val (ux, uy) = w.cellPoint(1)
        q.post(InputQueue.Type.DOWN, ux, uy)
        val seen = HashSet<Int>()
        repeat(200) {
            w.tick(q.drainTo(q.headSequence()))
            if (it == 1) q.post(InputQueue.Type.UP, ux, uy)
            seen += w.player.S
        }
        // jump chain: squat 21 -> rise 22/23/233 -> fall 43 -> land 5
        assertTrue(21 in seen || 22 in seen || 23 in seen || 233 in seen,
            "expected jump anims, saw $seen")
        assertTrue(43 in seen || 5 in seen,
            "expected fall/land, saw $seen")
    }

    @Test fun `ax11 soldiers patrol off their home cell`() {
        val w = world()
        val soldiers = w.npcs.filter { it.ax == 11 }
        assertTrue(soldiers.isNotEmpty(), "expected ax11 records in level 0")
        val homes = soldiers.map { it.ak }
        // au>=2 entities freeze verbatim (k.java L25f) and ax11 owns
        // P|16 itself — hold the player beside a soldier so the camera
        // keeps it in-play, exactly like a real walk-by.
        val s0 = soldiers.first()
        repeat(120) {
            w.player.setPositionPx(s0.ak + 20, s0.al)
            w.tick(emptyList())
        }
        val moved = soldiers.zip(homes).count { (e, hx) -> kotlin.math.abs(e.ak - hx) > 8 }
        assertTrue(moved > 0, "no soldier patrolled: ${soldiers.map { it.S }}")
    }

    @Test fun `soldier alerts and chases when player enters the zone box`() {
        val w = world()
        // park the player inside a soldier's Z[9..12] alert box
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        repeat(5) { w.tick(emptyList()) }
        w.player.setPositionPx(s.Z[9] + 5, s.al)
        // b() (i.java:1546) gates the spot on v() → au<=i, i.e. the
        // entity must be near the CAMERA — teleporting the player leaves
        // the cam behind; snap it like a real scroll would.
        w.kO = s.ak - 200; w.kP = s.al - 120
        var alerted = false
        repeat(90) {
            // the aA==0 → a() body-push (i.java:6246) shoves the player
            // each tick — re-park inside the zone like real input would;
            // an ax69 zone may bind af mid-run and blind l() (i.java:2290)
            w.player.setPositionPx(s.ak + 5, s.al)
            w.player.af = null
            w.tick(emptyList())
            if (s.aA != 0 || s.S == 5 || s.S == 4 || s.S == 23) alerted = true
        }
        assertTrue(alerted, "soldier should alert on player in zone (S=${s.S}, aA=${s.aA})")
    }

    @Test fun `alerted soldier strikes the player in melee range`() {
        val w = world()
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        repeat(5) { w.tick(emptyList()) }
        // stand the player next to the soldier inside its alert box
        w.player.setPositionPx(s.ak + 30, s.al)
        var struck = false
        repeat(200) {
            w.tick(emptyList())
            w.player.setPositionPx(s.ak + 30, s.al)   // keep in reach
            if (w.player.x1 < 90 || w.player.hitsTaken > 0 || w.player.S == 43)
                struck = true
        }
        assertTrue(struck,
            "soldier should land hits (S=${s.S}, x1=${w.player.x1})")
    }

    @Test fun `player vault attack damages and kills a soldier`() {
        val w = world()
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        repeat(5) { w.tick(emptyList()) }
        val hp0 = s.aB
        // pin player overlapping the soldier in an attack anim (67 sword combo)
        var sawDamage = false
        repeat(300) {
            w.player.setPositionPx(s.ak, s.al)
            if (w.player.S != 67) w.player.setAnim(67)
            s.setAnim(0)     // soldier fights back now (hit-react → i(6)
                            // lunge → strike → player stagger); pin passive
                            // to isolate the j() damage-intake chain
            w.tick(emptyList())
            if (s.aB < hp0) sawDamage = true
        }
        assertTrue(sawDamage, "player attacks should damage the soldier (aB=${s.aB})")
        // enough hits → aB<=0 → i(0) → i(139) corpse
        var corpse = false
        repeat(400) {
            w.player.setPositionPx(s.ak, s.al)
            if (s.aB > 0 && w.player.S != 67) w.player.setAnim(67)
            s.setAnim(0)
            w.tick(emptyList())
            if (s.S == 139) corpse = true
        }
        assertTrue(s.aB <= 0 && corpse,
            "soldier should die to corpse S139 (aB=${s.aB}, S=${s.S})")
    }

    @Test fun `bottom-zone tap swings the sword and can kill a soldier`() {
        val w = world()
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        // walk the player to the soldier and tap attack (bottom-third zone)
        w.player.setPositionPx(s.ak - 20, s.al)
        w.tick(emptyList())
        var sawSlash = false; var kill = false
        repeat(600) {
            if (s.aB <= 0) { kill = true; return@repeat }
            w.player.setPositionPx(s.ak - 20, s.al)
            s.setAnim(0)     // pin passive — the soldier now counterattacks
                            // faithfully; this test covers the kill chain
            val (cx, cy) = w.cellPoint(4)
            w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, cx, cy),
                          InputQueue.Event(1, InputQueue.Type.UP, cx, cy)))
            if (w.player.S in intArrayOf(67, 68, 69, 112, 113, 114, 115, 81)) sawSlash = true
        }
        assertTrue(sawSlash, "tap should enter the sword combo (S=${w.player.S})")
        assertTrue(kill, "combo hits should kill the soldier (aB=${s.aB}, S=${s.S})")
    }

    @Test fun `assassination finisher kills a weakened locked soldier`() {
        val w = world()
        settleIntro(w)                 // I() L108 gate: tests run post-intro
        val s = w.npcs.firstOrNull { it.ax == 11 } ?: return
        // the player is about to stand next to this soldier — put the
        // camera where it would be (k.O/k.P) so u() scores it in-play;
        // ax11's own arm clears P|16 when aA==0 so keep-live can't help.
        w.kO = s.ak - 200; w.kP = s.al - 120
        repeat(5) { w.tick(emptyList()) }
        // Verbatim weaken chain (i.java:1955): Z[0]==1 marks the soldier
        // weaken-eligible; a hit leaving aB<=bu → C() flips Z0=2 + S144.
        // (Level-0 records carry Z0=0 — they never weaken, proven.)
        s.Z[0] = 1
        s.aB = 120
        // +4px: feet must embed into the floor row (W[3]+1 inside cell-5)
        // or x() reports aZ=false and the :2473 arm falls before the hit
        // lands — same in the original.
        w.player.setPositionPx(s.ak - 20, s.al + 4)
        // Land a normal hit to trip the weaken: H=50 → aB=70 → hitReact
        // Z0==1 → Z0=2 + S144 + claims the aN lock.
        w.player.setAnim(67)
        w.tick(emptyList())
        assertTrue(s.Z[0] == 2 && s.S == 144,
            "hit on Z0==1 soldier should weaken: Z0=2+S144 (got Z0=${s.Z[0]}, S=${s.S})")
        assertTrue(w.lockTarget === s,
            "weakened soldier should hold the aN lock")
        // The weakened soldier counter-engages further normal attacks:
        // h() (i.java:1271) — S144 ∉{11,12,6} → i() forces the player to
        // S8 and takes S17 (aC=16) itself, preempting j().
        for (i in 0 until 30) {
            w.player.setPositionPx(s.ak - 20, s.al)
            val (cx, cy) = w.cellPoint(4)
            w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, cx, cy),
                          InputQueue.Event(1, InputQueue.Type.UP, cx, cy)))
            if (s.S == 17) break
        }
        assertTrue(s.S == 17,
            "weakened soldier should counter-engage the next attack (sS=${s.S})")
        // S216 is h()-exempt (i.java:1272): it reaches j()'s finisher arm
        // (i.java:1334) — aB=0 + diagonal launch (ag=±5120, ai=∓2560).
        // Wait out S17: its counter arm (i.java:6036) force-S8s any attacking
        // player — including the dive — so strike once the arm advances to
        // S11 (Z0==2 → i(11)), where tail[2] arms j() intake instead.
        for (i in 0 until 60) {
            w.player.setPositionPx(s.ak - 20, s.al)
            w.tick(emptyList())
            if (s.S != 17) break
        }
        assertTrue(s.S != 17, "counter-engage should resolve (sS=${s.S})")
        w.player.setAnim(216)
        for (i in 0 until 60) {
            w.player.setPositionPx(s.ak - 20, s.al)
            w.tick(emptyList())
            if (s.aB <= 0) break          // check the launch before friction decays it
        }
        assertTrue(s.aB <= 0,
            "S216 finisher should zero the victim (aB=${s.aB})")
        // i.g() (i.java:1237) zeroes ag/ai unconditionally — the ±5120
        // launch written before it is dead in the original; the victim
        // lands in S85 (the c(85,157) path) with ag=0.
        assertTrue(s.S == 85 || s.ag == 0,
            "S216 victim should sit in S85 with the launch eaten by g() (S=${s.S}, ag=${s.ag})")
    }

        @Test fun `npc strike on a metered player pays meter and staggers the player`() {
        val w = world()
        // pick a soldier whose strike-adjacent position passes i.c()'s
        // wall guard (open-air spots legitimately block the drain)
        var sv: Entity? = null
        var sdx = 0
        for (cand in w.npcs.filter { it.ax == 11 }) {
            keepLive(cand)
            cand.setAnim(12)
            // the strike X box is a clip-data rect (east or west of ak)
            // — stand the player inside its x-span on a grounded cell:
            // airborne victims fall out (op20, no S9) and off-side
            // spots simply never overlap the swing.
            outer@ for (dx in -40..40) {
                w.player.setPositionPx(cand.ak + dx, cand.al)
                w.player.refreshBoxes()
                w.player.probeCells(w)
                if (!w.player.nearLeftWall(w) && w.player.aZ &&
                    Entity.overlapI(w.player.W, cand.X)) { sv = cand; sdx = dx; break@outer }
            }
            if (sv != null) break
        }
        sv = assertNotNull(sv, "no grounded strike-adjacent spot found")
        var playerHit = false
        for (i in 0 until 300) {
            w.player.setPositionPx(sv.ak + sdx, sv.al)
            w.player.refreshBoxes()
            w.player.ag = 0; w.player.ah = 0
            w.tick(emptyList())
            // op4 arm → r9.c(r13): the VICTIM (player) hit-reacts (S9)
            if (w.player.S == 9) { playerHit = true; break }
        }
        assertTrue(playerHit, "strike on metered player → r9.c(r13) → player S9")
        assertTrue(w.player.x1 < 90, "g.a() pays meter u[0]=5 (x1=${w.player.x1})")
    }

    @Test fun `player knocked out at zero meter shows fail screen then reloads`() {
        val w = world()
        val spawn = w.player.ak to w.player.al
        repeat(5) { w.tick(emptyList()) }
        val (dx, dy) = damageSpot(w)
        w.player.setPositionPx(dx, dy)
        // knockdowns drain the meter via g.d() (u[0]=5): 90/5 = 18 ops;
        // reset g.t iframes between hits (each drain sets t=10)
        repeat(20) {
            w.player.applyHit(18, 0, null, w)
            w.player.gt = 0; w.iBh = 0
        }
        assertTrue(w.player.x1 <= 0, "meter should drain to 0 (x1=${w.player.x1})")
        // KO → k.l(12): fail screen freezes the world until the context tap
        w.tick(emptyList())
        assertTrue(w.failed, "x1<=0 must raise the mission-fail screen")
        assertEquals(1, w.deaths)
        val pos = w.player.ak to w.player.al
        repeat(5) { w.tick(emptyList()) }
        assertEquals(pos, w.player.ak to w.player.al, "world frozen while failed")
        // v(65568) edge = retry → f(false) full level reload
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, 200, 130),
                      InputQueue.Event(1, InputQueue.Type.UP, 200, 130)))
        assertFalse(w.failed, "YES row tap should dismiss the fail screen")
        assertEquals(90, w.player.x1, "reload refills the meter")
        assertEquals(spawn, w.player.ak to w.player.al, "player back at spawn")
    }

