    @Test fun `ax2 checkpoint fires on overlap and reload restores to it`() {
        val w = world()
        assertTrue(w.checkpoints.isNotEmpty(), "level 0 has ax2 records")
        val cp = w.checkpoints.first()
        overlapCheckpoint(w, cp)
        repeat(2) { w.tick(emptyList()) }
        assertTrue(cp.consumed, "checkpoint should fire on overlap")
        assertNotNull(w.checkpointSnap)
        assertEquals(cp.ak, w.checkpointSnap!!.ak)
        // die → fail → retry: player respawns at the checkpoint, not spawn
        val (dx, dy) = damageSpot(w)
        w.player.setPositionPx(dx, dy)
        repeat(20) {
            w.player.applyHit(18, 0, null, w)
            w.player.gt = 0; w.iBh = 0
        }
        w.tick(emptyList())
        assertTrue(w.failed)
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, 200, 130),
                      InputQueue.Event(1, InputQueue.Type.UP, 200, 130)))
        assertEquals(cp.ak, w.player.ak, "reload must restore checkpoint pos")
        // i.java:18634-18635: X() writes k.B.ak/al — the PLAYER's pos at
        // write time (cp.al+5 where the player stood), not the cp's.
        // The respawned player is airborne at that spot → l()→aw()→a(0)
        // = enterFall drops him onto the floor below (proven semantics —
        // the exact-pin only held under the old i(11) fold bug).
        repeat(15) { w.tick(emptyList()) }
        assertTrue(w.player.aZ, "respawned player settles onto the cp floor")
        assertTrue(w.player.al in (cp.al + 5)..(cp.al + 80),
            "lands on the floor under the write-time pos (was ${w.player.al})")
    }

    @Test fun `checkpoint stamps live npc state and keeps pre-checkpoint dead dead`() {
        // k.a(bb[i],as) is a save-image WRITE, not a re-home — the live
        // entity does not move; the restore re-materializes it at the
        // stamped position (simple i.java:13535+, k.java:4604).
        val w = world()
        val cp = w.checkpoints.first()
        val live = w.npcs.first { it.ax == 11 }
        val dead = w.npcs.last { it.ax == 11 }
        live.setPositionPx(live.homeX + 400, live.homeY)
        dead.setAnim(139) // killed before the checkpoint
        overlapCheckpoint(w, cp)
        repeat(2) { w.tick(emptyList()) }
        assertTrue(cp.consumed)
        assertEquals(live.homeX + 400, live.ak,
            "checkpoint pickup must not move the live npc")
        assertEquals(139, dead.S, "pre-checkpoint corpse stays dead")
        // reload: the live npc re-materializes at its stamped position,
        // the corpse's own stamped S=139 keeps it dead.
        val (dx, dy) = damageSpot(w)
        w.player.setPositionPx(dx, dy)
        repeat(20) {
            w.player.applyHit(18, 0, null, w)
            w.player.gt = 0; w.iBh = 0
        }
        w.tick(emptyList())
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, 200, 130),
                      InputQueue.Event(1, InputQueue.Type.UP, 200, 130)))
        val restored = w.npcs.first { it.aw == live.aw }
        assertEquals(live.homeX + 400, restored.ak,
            "live npc restored at its checkpoint-image position")
        assertEquals(139, w.npcs.first { it.aw == dead.aw }.S)
    }

