// Slice 47 — ax42 `bz()` fuse/timer zone + k.F claim slot
// ===========================================================================
class Slice47Test {

    private fun ax42At(w: Level0World, x: Int, y: Int, kind: Int, uid: Int, secs: Int): Entity {
        val e = Entity(42, null)
        e.setPositionPx(x, y)
        val f = mutableListOf(42, 0, x, y, kind, 0, 0, 0, 0, 20, 20, uid, secs)
        w.npcFsm.initAx42(e, f)
        w.npcs.add(e)
        return e
    }

    @Test fun `ax42 dormant records still claim kF + P bits every tick`() {
        val w = world(); w.npcs.clear()
        val e = ax42At(w, 0, 0, 0, 0, 30)
        assertEquals(-1, e.S, "no i() reaches ax42 in the ctor — S stays -1")
        w.kAJ = 0; w.kAM = 0
        w.npcFsm.tickAx42(e, w, w.player)
        assertSame(e, w.kF, "k.F = this")
        assertTrue(e.P and 16 != 0 && e.P and 512 != 0, "P|=16|512")
        assertEquals(0, w.kAJ, "S!=0 → aJ machine skipped")
        assertEquals(0, w.kAM)
    }

    @Test fun `ax42 kind0 fires when the bound entity expires`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 0, 77, 30)
        e.setAnim(0)                                          // arm: S==0
        // bound entity uid 77, dead (aB<=0 → P()==true)
        val dead = Entity(6, null); dead.aw = 77; dead.aB = 0
        w.npcs.add(dead)
        w.sfxLog.clear()
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(1, w.kAJ); assertEquals(-40, w.kAK); assertEquals(30, w.kAL)
        assertNull(e.s, "s=null after L27 fire")
        assertTrue(9 in w.sfxLog, "k.A(9) on fire")
    }

    @Test fun `ax42 kind0 waits while the bound entity lives`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 0, 77, 30)
        e.setAnim(0)
        val alive = Entity(6, null); alive.aw = 77; alive.aB = 10; alive.P = 32
        w.npcs.add(alive)
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(0, w.kAJ, "s.P&32 set → no fire")
        assertSame(alive, e.s, "s stays bound")
    }

    @Test fun `ax42 kind1 fires on bind even while s lives`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 1, 77, 45)
        e.setAnim(0)
        val alive = Entity(6, null); alive.aw = 77; alive.aB = 10; alive.P = 0
        w.npcs.add(alive)
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(1, w.kAJ, "Z0==1 && s.P&32==0 → L27 fire")
        assertEquals(45, w.kAL)
    }

    @Test fun `ax42 aJ2 expiry fails the mission`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak + 9000, p.al + 9000, 0, 77, 0)   // aL=0 → expires immediately
        e.setAnim(0)
        w.kAJ = 2; w.kAL = 0; w.kAM = 0; w.kBw = 0; w.kBx = 0
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(-1, w.kBw, "bw=-1")
        assertEquals(58, w.kBx, "aj!=7 → bx=58")
        assertEquals(-1, w.kAL); assertEquals(0, w.kAM)
        assertEquals(2, w.kAJ, "this arm doesn't write aJ")
    }

    @Test fun `ax42 aJ2 overlap while ticking collects`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax42At(w, p.ak, p.al, 0, 77, 10)                // aL=10s
        e.setAnim(0)
        w.kAJ = 2; w.kAL = 10; w.kAM = 0
        p.refreshBoxes(); e.refreshBoxes()
        w.npcFsm.tickAx42(e, w, p)
        assertTrue(e in w.pendingRemove, "player∩W → k.c(this)")
        assertEquals(3, w.kAJ)
        assertEquals(0, w.kBw, "no fail write")
    }

    @Test fun `ax42 kind2 expiry binds script then aa-steps it`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        // uid absent from k.eH → kSIndex = -1 → bindScript(-1) leaves
        // ca=-1 → claimActive false (the aJ==3 remove+reset tail).
        w.kEh = intArrayOf(999)
        val e = ax42At(w, p.ak + 9000, p.al, 2, 1234, 0)
        e.setAnim(0)
        w.kAJ = 2; w.kAL = 0; w.kAM = 0; w.kBw = 0
        w.npcFsm.tickAx42(e, w, p)
        assertEquals(3, w.kAJ)
        assertEquals(-1, e.ca, "h(k.s(Z[1])) → bindScript(-1)")
        w.npcFsm.tickAx42(e, w, p)
        assertTrue(e in w.pendingRemove, "!claimActive → k.c(this)")
        assertEquals(-1, w.kAL); assertEquals(0, w.kAM); assertEquals(2, w.kBw)
    }
}
// ---------------------------------------------------------------------------
// slice 44 — ax35 `bQ()` scripted multi-tool (i.java:21594-22296)
// ---------------------------------------------------------------------------
class Slice44Test {

    /** ax35 record fixture — sparse map per i.java:3614:
     *  `[35,uid,x,y,0,S,P,az,z0..z6,z10,z11,z13]`. */
    private fun ax35At(w: Level0World, x: Int, y: Int, s: Int,
                       az: Int = 0, z: IntArray = IntArray(0)): Entity {
        val e = Entity(35, w.clips[62])
        e.setPositionPx(x, y)
        val f = mutableListOf(35, 0, x, y, 0, s, 0, az)
        for (i in 0..6) f += if (z.size > i) z[i] else 0          // Z[0..6]
        f += if (z.size > 7) z[7] else 0                          // Z[10]
        f += if (z.size > 8) z[8] else 0                          // Z[11]
        f += if (z.size > 9) z[9] else 0                          // Z[13]
        w.npcFsm.initAx35(e, f, w)
        w.npcs.add(e)
        return e
    }

    private fun finish(e: Entity) {
        val c = e.clip ?: return
        e.T = c.frameCount(e.S) - 1
        e.U = c.frameDuration(e.S, e.T) - 1
    }

    @Test fun `ax35 init arm uses the sparse record map`() {
        val w = world(); w.npcs.clear()
        val e = ax35At(w, 300, 200, 0, az = 7,
            z = intArrayOf(1, 2, 30, 40, 1, 64, 5, 900, 12, 777))
        assertEquals(7, e.az)
        assertEquals(1, e.Z[0]); assertEquals(30, e.Z[2])
        assertEquals(64, e.Z[5]); assertEquals(5, e.Z[6])
        assertEquals(900, e.Z[10]); assertEquals(12, e.Z[11])
        assertEquals(777, e.Z[13])
        assertEquals(0, e.Z[7]); assertEquals(1, e.Z[12])
    }

    @Test fun `ax35 S0 resolves af then counts down into S1`() {
        val w = world(); w.npcs.clear()
        val af = Entity(11, w.clips[7]).apply { aw = 777; aB = 100 }
        w.npcs.add(af)
        val e = ax35At(w, 300, 200, 0, z = intArrayOf(0,0,20,20,0,0,0,0,0,777))
        e.aC = 1
        w.npcFsm.tickAx35(e, w, w.player)
        assertEquals(777, e.af?.aw, "af resolved via k.q(Z[13])")
        assertTrue(e.af!!.P and 16 != 0, "af.P |= 16")
        assertNotNull(w.volPaintRect, "vol paint ran")
        w.npcFsm.tickAx35(e, w, w.player)
        assertEquals(1, e.S, "aC expiry -> i(1)")
        assertEquals(191, af.S, "af.i(191) on handoff")
    }

    @Test fun `ax35 S0 dead af clears the vol rect and sets P=32`() {
        val w = world(); w.npcs.clear()
        val e = ax35At(w, 300, 200, 0, z = intArrayOf(0,0,20,20,0,0,0,0,0,999))
        w.npcFsm.tickAx35(e, w, w.player)   // af never resolves (no uid 999)
        assertEquals(32, e.P)
        assertNull(w.volPaintRect)
    }

    @Test fun `ax35 S1 captures player midline and enters the wave arm`() {
        val w = world(); w.npcs.clear()
        val af = Entity(11, w.clips[7]).apply { aw = 777; aB = 100 }
        w.npcs.add(af)
        val e = ax35At(w, 300, 200, 1, z = intArrayOf(0,0,20,20,0,0,0,0,0,777))
        e.af = af                                     // resolved by an S0/29 tick
        finish(e)
        w.npcFsm.tickAx35(e, w, w.player)
        assertEquals(w.player.ak, e.Z[8], "Z[8] = aS.ak")
        assertEquals((w.player.W[1] + w.player.W[3]) shr 1, e.Z[9],
            "Z[9] = aS W-mid-y")
        assertEquals(2, e.S, "S1 -> i(2) (S30 would take i(31))")
        assertTrue(27 in w.sfxLog, "k.A(27) on the wave arm")
    }

    @Test fun `ax35 sweep insta-kills an overlapping soldier`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        p.setPositionPx(-5000, -5000); p.refreshBoxes()   // off the vol
        val e = ax35At(w, 300, 200, 6)
        e.aG = 0                                          // march straight up
        val o = Entity(11, w.clips[7]).apply {
            aB = 100; setPositionPx(330, 200); refreshBoxes() }
        w.npcs.add(o)
        e.refreshBoxes()
        w.npcFsm.tickAx35(e, w, p)
        assertEquals(0, o.aB, "as() zeroes aB on overlap")
        assertEquals(0, o.S, "ax11 -> i(0) death anim")
    }

    @Test fun `ax35 flight march commits only into free cells`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        p.setPositionPx(-5000, -5000); p.refreshBoxes()
        val e = ax35At(w, 300, 200, 6)
        e.aG = 192                                          // down-screen
        // force the next-step cell solid: park the march over a floor
        val sx = e.ak; val sy = e.al
        var guard = 0
        // march until despawn or a cell-20 bounce (bounded)
        while (e.S == 6 && guard++ < 200) w.npcFsm.tickAx35(e, w, p)
        // it either turned (S10+bR) or despawned — both proven arms
        assertTrue(e.S != 6 || w.npcs.none { it === e },
            "march resolves to quadrant anim or edge despawn (S=${e.S})")
    }

    @Test fun `ax35 S26 resets wave counters and enters S27`() {
        val w = world(); w.npcs.clear()
        val e = ax35At(w, 300, 200, 26)
        e.aC = 9; e.Z[7] = 4; e.Z[12] = 3
        finish(e)
        w.npcFsm.tickAx35(e, w, w.player)
        assertEquals(0, e.aC); assertEquals(0, e.Z[7])
        assertEquals(1, e.Z[12])
        assertEquals(27, e.S)
        assertTrue(27 in w.sfxLog)
    }

    @Test fun `ax35 wave step spawns the S18 marker plus an f() child`() {
        val w = world(); w.npcs.clear()
        val af = Entity(11, w.clips[7]).apply { aw = 777; aB = 100 }
        w.npcs.add(af)
        // Z[5]=125° (26 of the 28 ax35 records in m0/m2/m3/m6/m7; the
        // other two are 60°), θ=88:
        // the L118 march steps `20·sin θ` up per turn and only ends above
        // k.P, so θ needs sin θ > 0 — angle 0 never terminates in the
        // original either (j.b = cos, slice 352). Z[8]/Z[9] = fire point.
        val e = ax35At(w, 300, 100, 2,
            z = intArrayOf(0,0,20,20,0,125,10,0,0,777))
        e.af = af
        e.Z[8] = 300; e.Z[9] = 100; e.aC = 1
        w.kP = 40                      // kP: march endpoint stays in-map
        finish(e)
        w.npcFsm.tickAx35(e, w, w.player)
        assertTrue(w.pendingInsert.size >= 2,
            "L124 spawns the S18 marker + the f() wave child")
        assertTrue(w.pendingInsert.any { it.S == 18 }, "a(35,62,18,300)")
        assertEquals(1, e.Z[7], "wave counter advanced")
    }

    @Test fun `ax35 S28 aim proxy follows held d-pad and feeds af`() {
        val w = world(); w.npcs.clear()
        val af = Entity(11, w.clips[7]).apply { aw = 777; aB = 100 }
        w.npcs.add(af)
        val e = ax35At(w, 300, 200, 28, z = intArrayOf(0,0,0,0,0,0,0,0,0,777))
        e.af = af
        w.player.setPositionPx(300, 200); w.player.refreshBoxes()
        w.kM(2)                              // m(ad) snap → entity in view
        w.kAT = true
        w.pad.edge = 0; w.pad.held = 8256                       // k.u(8256)
        w.npcFsm.tickAx35(e, w, w.player)
        assertEquals(310, e.ak, "RIGHT +10px (k.u held)")
        w.pad.held = 16388
        w.npcFsm.tickAx35(e, w, w.player)
        assertEquals(190, e.al, "UP -10px")
        assertEquals(310, af.Z[8]); assertEquals(190, af.Z[9],
            "L232 feeds the aim point to the af director")
        w.kAT = false
        w.npcFsm.tickAx35(e, w, w.player)
        assertTrue(e in w.pendingRemove, "!k.aT -> k.c(this)")
    }

    @Test fun `ax35 S23 grab-scan latches the player and S24 flings`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        p.setAnim(18)                                          // grabbable
        p.setPositionPx(300, 200); p.refreshBoxes()
        val e = ax35At(w, 300, 200, 23)
        e.refreshBoxes()
        w.npcFsm.tickAx35(e, w, p)
        assertTrue(p.ga === e, "g.a = this")
        assertEquals(260, p.S, "S264->i(262) else i(260)")
        assertEquals(e.al, p.al)
        // S24: release-fling arms the 2560 fall
        e.setAnim(24)
        w.npcFsm.tickAx35(e, w, p)
        assertNull(p.ga, "g.a released")
        assertEquals(2560, p.ah, "aS.a(2560) fling vy")
        finish(e)
        w.npcFsm.tickAx35(e, w, p)
        assertEquals(128, e.P and 128, "P=128 carry-armed")
        assertEquals(20, e.S, "i(20) carry-return")
    }

    @Test fun `ax35 S14 off-camera containment removes the entity`() {
        val w = world(); w.npcs.clear()
        val e = ax35At(w, -8000, -8000, 15)
        e.Y[0] = -8000; e.Y[1] = -8000; e.Y[2] = -7999; e.Y[3] = -7999
        w.npcFsm.tickAx35(e, w, w.player)
        assertTrue(e in w.pendingRemove, "!b(Y,k.ac) -> k.c(this)")
    }
}

// ---------------------------------------------------------------------------
// slice 45 — ax13 `aW()` rope/vine swing (i.java:13182-13367)
// ---------------------------------------------------------------------------
class Slice45Test {

    /** ax13 record fixture — the shared L111 map:
     *  `[13,uid,x,y,aE,S,P,?, ?, ?, ?, aF,o,p,aG,ay]`. */
    private fun ax13At(w: Level0World, x: Int, y: Int, s: Int = 0,
                       ag: Int = 0, z1: Int = 10): Entity {
        val e = Entity(13, null)
        e.setPositionPx(x, y)
        // L502 init reads the aG variant from r8[4]: {1→1, 2→2, 3→4}.
        val f = mutableListOf(13, 0, x, y,
            when (ag) { 1 -> 1; 2 -> 2; 4 -> 3; else -> 0 }, s, 0)
        for (i in 7..15) f += 0
        w.npcFsm.initAx13(e, f)
        e.Z[1] = z1        // rope segment count
        w.npcs.add(e)
        return e
    }

    @Test fun `ax13 pendulum integrates only while displaced`() {
        val w = world(); w.npcs.clear()
        val e = ax13At(w, 100, 100)
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(0, e.bP); assertEquals(0, e.bO)   // L5: bP==0 skips L6
        e.bO = 256                                      // displace → L6 runs
        val p0 = e.bP
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(p0 + (256 shl 1), e.bP, "bP += bO<<1")
        assertTrue(e.bO < 256, "bO -= sin(n-θ)<<1 restoring force")
    }

    @Test fun `ax13 swing-side sign flip damps velocity by an eighth`() {
        val w = world(); w.npcs.clear()
        val e = ax13At(w, 100, 100)
        e.bO = -512; e.bP = 512                         // swinging left, +angle
        e.j = 1
        // integrate: bP += -1024 → negative → sign flip → damp
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(-1, e.j, "side latch follows bP sign")
    }

    @Test fun `ax13 grab latch binds the player and arms the hang`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax13At(w, p.ak, p.al - 40, ag = 0, z1 = 10)
        e.bN = 6                                          // rope mid-swing
        p.setAnim(18)                                     // grabbable (g.b)
        p.N = p.ak shl 8; p.O = (e.O + 2000)             // inside arc box
        p.refreshBoxes()
        // drive the arc box against the player's W
        w.npcFsm.tickAx13(e, w, p)
        if (p.bM === e) {
            assertEquals(1, e.aA, "aA=1 attached")
            assertEquals(101, p.az, "aS.az=101")
            assertTrue(p.aA and 64 != 0, "aS.aA|=64")
            assertEquals(326, p.S, "i(326) hang anim")
        } else {
            // geometry-dependent arm — assert no crash at minimum
            assertTrue(e.aA == 0 || p.bM === e)
        }
    }

    @Test fun `ax13 aG4 spawner counts segments while the ax58 gate is open`() {
        val w = world(); w.npcs.clear()
        val e = ax13At(w, 100, 100, ag = 4, z1 = 10)
        e.Z[6] = -1                                       // no link → grow
        e.bN = 2
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(3, e.bN, "Z[6]==-1 → bN++")
        e.bN = 10
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(10, e.bN, "bN >= Z[1] caps the spawner")
        val door = Entity(58, null).apply { aw = 42; setAnim(2) }  // closed
        w.npcs.add(door)
        e.Z[6] = 42; e.bN = 2
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(2, e.bN, "linked + !bf() → no growth")
        door.setAnim(1)                                    // bf() open set
        w.npcFsm.tickAx13(e, w, w.player)
        assertEquals(3, e.bN, "bf() gate open → bN++")
    }

    @Test fun `ax13 release flings the rider with the aG1 leap arc`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax13At(w, p.ak, p.al - 40, ag = 1)
        e.aA = 1; e.bM = p; p.bM = e; p.aA = p.aA or 64
        e.bO = 300; e.bP = -512                          // velocity flip window
        val o0 = e.bO
        // integrator flips bO sign → r0*bO<0 → aS.j()
        repeat(6) { if (p.bM === e) w.npcFsm.tickAx13(e, w, p) }
        assertNull(p.bM, "release unlinks")
        assertTrue(p.S == 23 || p.bM === e, "aG1 → i(23) leap")
    }

    @Test fun `g k rope input pumps and climbs`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax13At(w, 100, 100, ag = 1, z1 = 10)
        e.aA = 1; e.bM = p; p.bM = e
        e.bN = 5
        e.bO = 0; e.bP = 0            // dead pendulum — bound at rest
        p.setAnim(326)
        // UP held with dead pendulum → climb one segment (L92)
        w.pad.held = 16388
        w.npcFsm.tickAx13(e, w, p)
        assertEquals(4, e.bN, "u(16388) → bN--")
        assertEquals(82, p.S, "i(82) climb anim")
        // descend at bottom of rope → L113 drop keeps bM (verbatim)
        e.bN = 9; p.setAnim(326); p.aA = p.aA or 64
        w.pad.held = 33024
        e.bO = 0; e.bP = 0
        w.npcFsm.tickAx13(e, w, p)
        assertEquals(43, p.S, "bN+2 > Z[1]-2 → i(43) drop")
        assertTrue(p.bM === e, "verbatim: L116 does not clear aS.bM")
    }
}


// =====================================================================
// Slice 43c — i.a() big-op decoder (script ops 100-114).
// =====================================================================

private fun op100(uid: Int, sub: Int, arg: Int) =
    byteArrayOf(100) + u16le(uid) + u16le(sub) + u16le(arg)
private fun op101(v: Int) = byteArrayOf(101) + u16le(v)
private fun op102(id: Int, flag: Int) = byteArrayOf(102) + u16le(id) + u16le(flag)
private fun op104(v: Int) = byteArrayOf(104) + u16le(v)
private fun op105(r9: Int, str: Int, r11: Int) =
    byteArrayOf(105, r9.toByte()) + u16le(str) + byteArrayOf(r11.toByte())
private fun op106(uid: Int, a: Int, b: Int, c: Int, d: Int) =
    byteArrayOf(106) + u16le(uid) + u16le(a) + u16le(b) + u16le(c) +
        byteArrayOf(d.toByte())
private fun op107(mask: Int) = byteArrayOf(107) + u16le(mask)
private fun op108(pass: Int, fail: Int) =
    byteArrayOf(108) + u16le(pass) + u16le(fail)
private fun op109(x0: Int, y0: Int, x1: Int, y1: Int) =
    byteArrayOf(109) + u16le(x0) + u16le(y0) + u16le(x1) + u16le(y1)
private fun op110(a: Int, b: Int) = byteArrayOf(110) + u16le(a) + u16le(b)
private fun op111(s: Int, x: Int, y: Int, f: Int, az: Int) =
    byteArrayOf(111) + u16le(s) + u16le(x) + u16le(y) +
        byteArrayOf(f.toByte()) + u16le(az)
private fun op112(a: Int, b: Int, c: Int) =
    byteArrayOf(112) + u16le(a) + u16le(b) + u16le(c)
private fun op113(pass: Int, fail: Int) =
    byteArrayOf(113) + u16le(pass) + u16le(fail)
private fun op114(str: Int, cd: Int) =
    byteArrayOf(114) + u16le(str) + u16le(cd)

class Slice43cTest {

    // -- prologue (i.java:20060): only 108/113 run bodies before key ---

    @Test fun `non-108 ops are consumed but only fire at step==key`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(10, op101(5))))
        val e = claimer(w)
        e.runClaimScript(w)                    // r02=0: consumed, not fired
        assertEquals(-1, e.cP, "op101 must not write cP before its key")
        repeat(9) { e.runClaimScript(w) }      // r02=1..9
        assertEquals(-1, e.cP)
        e.runClaimScript(w)                    // r02=10 = key: fires
        assertEquals(5, e.cP)
    }

    // -- op100 (L12): uid/sub dispatch + the r04 arg-switch -------------

    @Test fun `op100 sub1 arg-switch 0 arms P32+P128 and drops ae link`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op100(900, 1, 0))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900; P = 16 }
        t.ae = Entity(11, null)
        w.npcs.add(t)
        e.runClaimScript(w)
        assertTrue(t.P and 32 != 0 && t.P and 128 != 0, "r04=0 → P|=32|128")
        assertEquals(0, t.P and 16, "r04=0 → P&=~16")
        assertNull(t.ae, "r04=0 → G() drops ae")
    }

    @Test fun `op100 sub0 skips when arg is 0, runs arg-switch otherwise`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op100(0, 0, 0)), scriptGroup(1, op100(0, 0, 5))))
        val e = claimer(w)
        val before = e.P
        e.runClaimScript(w)                    // sub0 arg0 → no-op
        assertEquals(before, e.P)
        e.runClaimScript(w)                    // sub0 arg5 → P^=1024
        assertTrue(e.P and 1024 != 0, "r04=5 → P^1024")
    }

    @Test fun `op100 sub2 removes the uid entity`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op100(900, 2, 0))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900 }
        w.npcs.add(t)
        e.runClaimScript(w)
        assertTrue(t in w.pendingRemove, "sub2 → k.c(r05)")
    }

    @Test fun `op100 sub4 az-flag and sub5 az-write`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op100(900, 4, 77)), scriptGroup(1, op100(0, 5, 55))))
        val e = claimer(w)
        val t = Entity(11, null).apply { aw = 900 }
        w.npcs.add(t)
        e.runClaimScript(w)
        assertTrue(w.kAb, "sub4 → k.ab = true")
        assertEquals(77, t.az, "sub4 → r05.az = r04")
        e.runClaimScript(w)
        assertEquals(55, e.az, "sub5 uid0 → this.az = r04")
    }

    @Test fun `op100 arg4 clears P512 and zeroes velocity`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op100(900, 1, 4))))
        val e = claimer(w)
        val t = Entity(11, null).apply {
            aw = 900; P = 512 + 32; ah = 100; ag = 50; ai = 25; aj = 10
        }
        w.npcs.add(t)
        e.runClaimScript(w)
        assertEquals(0, t.P and 512, "r04=4 → P&=~512")
        assertEquals(0, t.ah); assertEquals(0, t.ag)
    }

    // -- op101/op102/op104 ---------------------------------------------

    @Test fun `op101 stores cP which releaseClaim rebinds`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op101(7), opAnim(9))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(7, e.cP)
        w.kC = e                                    // cP handoff needs kC
        e.releaseClaim(w)
        assertEquals(-1, e.cP, "cP consumed by the bI tail")
        assertEquals(0, e.ca, "h/k(k.s(7)) → script idx 0")
        assertEquals(0, e.scriptStep, "k() reset the step")
    }

    @Test fun `op102 plays sfx either way — kz and kA share the body`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op102(33, 0), op102(44, 1))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(listOf(33, 44), w.sfxLog)
    }

    @Test fun `op104 writes the screen-transition statics`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op104(-5)), scriptGroup(1, op104(3))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(5, w.kCO); assertEquals(false, w.kCP)
        e.runClaimScript(w)
        assertEquals(3, w.kCO); assertEquals(true, w.kCP)
    }

    // -- op105 dialog (L76) ---------------------------------------------

    @Test fun `op105 arms the dialog modal and halts the script`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op105(3, 42, 1))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertTrue(e.cd[0], "cd[0]=true halt")
        assertTrue(w.dialogModal, "k.b accept → k.l(21)")
        assertEquals(1, w.bO); assertEquals(3, w.bN0); assertEquals(42, w.dialogLine)
        // case-21 u==9 semantics (bytecode 3466-3632 — the jadx
        // linearization hides it): a press edge while typing only
        // forces `bT=-1` (reveal); a press once revealed falls into
        // the SHARED advance arm `x=48; D(v+1)` (3604-3629) reached
        // via 3568-3581 (`v(65568) && u!=8 → 3604`). With v+1==w the
        // terminal `v==w && u==9 → C.Z(); l(8)` fires the same tick.
        w.autoDismissDialog = false
        w.kC = e
        w.pad.e(Pad.M_CONTEXT); w.tick(emptyList())
        assertTrue(w.dialogModal, "press while typing reveals, not dismisses")
        assertEquals(-1, w.dlgBT)
        w.pad.e(Pad.M_CONTEXT); w.tick(emptyList())
        assertFalse(w.dialogModal,
            "revealed press → D(v+1): v 0→1=w → C.Z(); l(8) (:3604/:985)")
        assertEquals(1, w.dlgV)
        assertFalse(e.cd[0], "Z() resumed the claim")
        // the same press does not leak a gameplay edge
        assertEquals(0, w.pad.edge)
    }

    // -- op106 (L84) ----------------------------------------------------

    @Test fun `op106 writes the dialog-box cQ on cT`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op106(0, 11, 22, 33, 3))))
        val e = claimer(w)
        e.runClaimScript(w)
        val q = e.cT!!.cQ!!
        assertEquals(11, q[5]); assertEquals(22, q[6]); assertEquals(-1, q[2])
        assertEquals(33, q[3]); assertEquals(1, q[8], "r016=3 → q[8]=3-2")
        assertEquals(-1, q[7], "r012=0 → cQ[7] keeps its -1 init")
        assertEquals(1, q[9], "r016>1 → q[9]=1")
    }

    // -- op107 (L106) ---------------------------------------------------

    @Test fun `op107 normalizes the key mask and spawns the prompt`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op107(32))))
        w.cm = 0                                             // unmounted arm
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(65568, e.cb!![0], "raw 32 → pad mask 65568")
        assertEquals(5, e.cb!![2], "bit position of 32")
        assertEquals(0, e.cb!![1])
        val pr = Entity.scriptPrompts[0]!!
        assertEquals(74, pr.clipIdx, "unmounted → touch-art clip74")
        assertEquals(0, pr.e)   // setState(0,-1) writes the frame slot
    }

    @Test fun `op107 mounted mode uses key-art clip9 + ct frames`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op107(4))))
        w.cm = 1
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(16388, e.cb!![0]); assertEquals(2, e.cb!![2])
        val pr = Entity.scriptPrompts[0]!!
        assertEquals(9, pr.clipIdx)
        assertEquals(Entity.CT[2], pr.e, "ct[cb[2]] prompt frame")
        w.cm = 0
    }

    // -- op108 single-button QTE (L133) ---------------------------------

    @Test fun `op108 press sets cb1 and the key branches to pass`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op107(32)),
            scriptGroup(10, op108(7, 0))))
        val e = claimer(w)
        e.runClaimScript(w)                     // op107 arms cb[0]=65568
        w.pad.edge = 65568
        repeat(10) { e.runClaimScript(w) }      // polls r02=1..10
        // step10 = key: the recorded press (cb[1]==1) && pass-uid>0 →
        // h/k(k.s(7)) rebind + return -1 (cb re-alloc'd back to [1]=-1)
        assertEquals(0, e.ca, "pass branch rebinds script idx 0 (uid7)")
        assertEquals(0, e.scriptStep)
        assertEquals(-1, e.cb!![1], "k() re-alloc'd cb after the branch")
    }

    @Test fun `op108 at key with no press branches to fail`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op107(32)),
            scriptGroup(5, op108(0, 7))))
        val e = claimer(w)
        repeat(5) { e.runClaimScript(w) }       // polls: cb[1] stays 0
        e.runClaimScript(w)                     // step5 = key: fail branch
        // fail uid → h/k(k.s(7)) rebind; k() re-alloc'd cb ([1]=-1)
        assertEquals(-1, e.cb!![1])
        assertEquals(0, e.scriptStep, "h/k rebind ran on the fail uid")
    }

    // -- op109/op110 carrier track (L184/L196) ---------------------------

    @Test fun `op109 fills cf and arms cd9 only at the key`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(5, op109(0, 0, 10, 5))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertNull(e.cf, "op109's body only runs at step==key")
        assertFalse(e.cd[9])
        repeat(4) { e.runClaimScript(w) }       // steps 1..4 still not key
        assertNull(e.cf)
        e.runClaimScript(w)                     // step5 = key: fills + arms
        assertEquals(0, e.cf!![0]); assertEquals(0, e.cf!![1])
        assertEquals(10, e.cf!![2]); assertEquals(5, e.cf!![3])
        assertTrue(e.cf!![4] != 0, "cf[4] = atan2 track angle")
        assertTrue(e.cd[9])
    }

    @Test fun `op110 binds the cg-ch pair and arms cd9 at key`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(3, op110(900, 901))))
        val e = claimer(w)
        val a = Entity(11, null).apply { aw = 900 }
        val b = Entity(11, null).apply { aw = 901 }
        w.npcs.add(a); w.npcs.add(b)
        e.runClaimScript(w)
        assertNull(e.cg, "op110's body only runs at step==key")
        assertFalse(e.cd[9])
        repeat(2) { e.runClaimScript(w) }
        assertNull(e.cg)
        e.runClaimScript(w)                     // step3 = key
        assertSame(a, e.cg); assertSame(b, e.ch)
        assertTrue(e.cd[9])
    }

    // -- op111 (L203) ----------------------------------------------------

    @Test fun `op111 spawns the ax8 param projectile only when kBK`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op111(7, 300, 200, 1, 99))))
        val e = claimer(w)
        e.runClaimScript(w)                     // kBK=false → nothing
        assertTrue(w.pendingInsert.isEmpty())
        w.kBK = true
        val e2 = claimer(w)
        e2.runClaimScript(w)
        assertEquals(1, w.pendingInsert.size)
        val p = w.pendingInsert[0]
        assertEquals(8, p.ax)
        assertTrue(p.P and 512 != 0, "param spawn P|=512")
        assertEquals(300, p.ak); assertEquals(200, p.al); assertEquals(99, p.az)
        assertTrue(p.av, "facing u8>0 → av")
    }

    // -- op112/op113 sequential choices (L209/L238) ----------------------

    @Test fun `op112 filters choices 0-9 and arms prompts + cc`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op112(2, 5, 99))))
        val e = claimer(w)
        e.runClaimScript(w)
        val c = e.cc!!
        assertEquals(2, c[0], "99 filtered out")
        assertEquals(2, c[1]); assertEquals(5, c[2])
        assertEquals(0, c[4])
        assertNotNull(Entity.scriptPrompts[0]); assertNotNull(Entity.scriptPrompts[1])
        assertNull(Entity.scriptPrompts[2])
    }

    @Test fun `op113 walks choices in order then branches at key`() {
        val w = scriptedWorld(scriptBlock(0, 0,
            scriptGroup(0, op112(1, 2, 10)),   // 10 out of range → 2 choices
            scriptGroup(10, op113(7, 0))))
        val e = claimer(w)
        e.runClaimScript(w)                     // op112: cc=[2][1,2]
        w.pad.edge = 1 shl 1                    // 1<<cc[1] = first choice
        e.runClaimScript(w)
        assertEquals(1, e.cc!![4])
        w.pad.edge = 1 shl 2                    // 1<<cc[2] = second choice
        e.runClaimScript(w)
        assertEquals(2, e.cc!![4], "both choices pressed in order")
        w.pad.edge = 0
        repeat(8) { e.runClaimScript(w) }       // steps to the key
        // step10 = key: cc[4]==cc[0] → pass uid7 → rebind + cc=null
        assertNull(e.cc)
        assertEquals(0, e.scriptStep)
    }

    // -- op114 (L299) ----------------------------------------------------

    @Test fun `op114 writes the HUD objective line and countdown`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op114(9, 300))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertEquals(300, w.kAO)
        // kAP = levelString(1+k.aj, 9) — empty table → null, write still ran
        assertNull(w.kAP)
    }
}


/** Pointer-field lifecycle regression (Devin Review, PR #52): `k.H/k.I`
 *  are the pointer-RELEASE point held for exactly one frame
 *  (k.java:548-553 writes them on pointerReleased; k.java:1874-77 copies
 *  and clears `ch/ci` every frame). A DOWN-only tap leaves no residue —
 *  stale taps must not resolve later `k.c`/`k.j` polls. */
class PointerLifecycleTest {
    @Test fun `k H,I fill on release and clear at tick end`() {
        val w = world()
        // DOWN alone must not populate the release fields
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, 100, 100)))
        assertEquals(-1, w.lastTouchX)
        assertEquals(-1, w.lastTouchY)
        // even when set mid-tick (release path), fields clear at tick end
        w.lastTouchX = 50; w.lastTouchY = 60
        w.tick(emptyList())
        assertEquals(-1, w.lastTouchX)
        assertEquals(-1, w.lastTouchY)
    }

    @Test fun `k J,K persist while touching and clear after release`() {
        val w = world()
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, 30, 40)))
        assertEquals(30, w.lastMoveX); assertEquals(40, w.lastMoveY)
        w.tick(emptyList())                       // held: position kept
        assertEquals(30, w.lastMoveX)
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.UP, 50, 60)))
        // k.java:1509-1514 — J=cj samples the release point, THEN `cl`
        // clears cj/ck for the following frame.
        assertEquals(50, w.lastMoveX); assertEquals(60, w.lastMoveY)
        w.tick(emptyList())
        assertEquals(-1, w.lastMoveX)
        assertEquals(-1, w.lastMoveY)
    }
}


// ---------------------------------------------------------------------------
// slice 48 — ax9 `bM()` contact block + `a()` push + `l()` overlay
// (i.java:21069-21196 / :914-993 / :21198 / init L50 :2781)
// ---------------------------------------------------------------------------
class Slice48Test {

    private fun ax9At(w: Level0World, x: Int, y: Int, s: Int,
                      link: Int = -1, kind8: Int = 0): Entity {
        val e = Entity(9, w.clips[47])
        e.setPositionPx(x, y)
        val f = mutableListOf(9, 0, x, y, 0, s, 0, link, kind8)
        for (i in 9..15) f += 0
        w.npcFsm.initAx9(e, f, w)
        w.npcs.add(e)
        return e
    }

    @Test fun `init S0 binds kAV and loads Z`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 100, 100, 0, link = 555, kind8 = 1)
        assertSame(e, w.kAV, "r8[5]==0 → k.aV = this (i.java:2786)")
        assertEquals(10, e.aB)
        assertEquals(99, e.az)
        assertEquals(0, e.Z[0])
        assertEquals(555, e.Z[1], "Z[1] = r8[7] link uid")
        assertEquals(72, e.Z[2], "Z[2] = k.bn[1] = 72 (k.java:8447)")
        assertEquals(0, e.S, "L392 i(r8[5])")
    }

    @Test fun `init S34 hidden variant skips Z`() {
        val w = world(); w.npcs.clear()
        w.kAV = null                              // level-0 S0 record bound it
        val e = ax9At(w, 100, 100, 34, link = 555)
        assertEquals(0, e.Z[1], "S34 → P|=512, Z untouched")
        assertTrue(e.P and 512 != 0)
        assertNull(w.kAV, "S34 does not claim k.aV")
    }

    @Test fun `preamble binds Z-1 link to ax51 and rides it`() {
        val w = world(); w.npcs.clear()
        val crate = Entity(51, w.clips[7])
        crate.aw = 777; crate.setPositionPx(200, 200)
        crate.ag = 2560; crate.refreshBoxes()
        w.npcs.add(crate)
        val e = ax9At(w, 200, 200, 0, link = 777)
        w.npcFsm.tickAx9(e, w, w.player)
        assertSame(crate, e.s, "k.q(Z[1]) ax51 overlap → s link")
        // ride arms: az = s.az + 1, al on top of the crate's W
        assertEquals(crate.az + 1, e.az)
        assertEquals(crate.W[1] - (e.Y[3] - e.Y[1]) + 5, e.al)
    }

    @Test fun `contact arm presses i-2 on player-X overlap`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, w.player.ak, w.player.al, 0)
        w.player.refreshBoxes()
        val p = w.player                          // give aS.X a real attackbox
        p.X[0] = e.W[0] - 5; p.X[1] = e.W[1] - 5
        p.X[2] = e.W[2] + 5; p.X[3] = e.W[3] + 5
        w.npcFsm.tickAx9(e, w, w.player)
        assertEquals(2, e.S, "W∩aS.X → i(2) then a() (L30)")
    }

    @Test fun `contact arm pushes player off the left side`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        // entity to the player's right, overlapping, p moving right or still
        val e = ax9At(w, p.ak + 4, p.al, 0)
        p.ag = 0; p.refreshBoxes(); e.refreshBoxes()
        // make W overlap certain: give e a W around the player
        e.W[0] = p.ak - 40; e.W[1] = p.al - 40
        e.W[2] = p.ak + 40; e.W[3] = p.al + 40
        val before = p.ak
        e.pushContact(w)
        assertTrue(p.ak < before, "L50 left-block snaps player left")
        assertEquals(0, p.ag, "L63 zeroes ag")
    }

    @Test fun `L57 right-block snaps player right and sets ag 1`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax9At(w, p.ak - 4, p.al, 0)
        p.ag = -1; p.refreshBoxes()
        e.W[0] = p.ak - 40; e.W[1] = p.al - 40
        e.W[2] = p.ak + 40; e.W[3] = p.al + 40
        e.pushContact(w)
        assertEquals(1, p.ag, "L57 sets ag=1 then falls to L25")
    }

    @Test fun `S139 corpse skips push entirely`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = ax9At(w, p.ak, p.al, 0)
        e.S = 139; p.refreshBoxes()
        val px = p.ak
        e.pushContact(w)
        assertEquals(px, p.ak)
    }

    @Test fun `ax15 grapple arm snaps player onto edge and claims g-a`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        val e = Entity(15, w.clips[7])
        e.setPositionPx(p.ak + 4, p.al); e.refreshBoxes()
        e.S = 6                                             // grapple anim
        e.W[0] = p.ak - 40; e.W[1] = p.al - 40
        e.W[2] = p.ak + 40; e.W[3] = p.al + 40
        p.refreshBoxes(); p.ac = e                          // held claim released
        p.S = 18                                            // g.b() free set
        e.pushContact(w)
        assertSame(e, p.ga, "g.a = this")
        assertEquals(209, p.S, "aS.i(209) grab anim")
        assertNull(p.ac, "aS.a(null) claim released")
        assertEquals(e.W[1] + 1, p.al)
    }

    @Test fun `l overlay spawns clip31 ax43 child and mirrors`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 300, 300, 18)
        e.T = 4
        w.npcFsm.tickAx9(e, w, w.player)
        val ad = e.ad
        assertNotNull(ad, "l(7) spawns the overlay child")
        assertEquals(43, ad!!.ax); assertEquals(7, ad.S)
        assertEquals(e.ak, ad.ak); assertEquals(e.al, ad.al)
        assertEquals(4, ad.T, "ad.T mirrors parent T")
        assertEquals(e.az + 1, ad.az)
        val first = ad
        w.npcFsm.tickAx9(e, w, w.player)
        assertSame(first, e.ad, "ad reused — no respawn")
    }

    @Test fun `S21 drops overlay and anim-end goes S22`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 300, 300, 21)
        w.npcFsm.tickAx9(e, w, w.player)
        assertNull(e.ad, "L61 ad=null")
        // force anim end → i(22)
        e.T = w.clips[47]!!.frameCount(e.S) - 1
        e.U = w.clips[47]!!.frameDuration(e.S, e.T) - 1
        w.npcFsm.tickAx9(e, w, w.player)
        assertEquals(22, e.S)
    }

    @Test fun `S2 wind-down goes i-3 on anim end`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 300, 300, 2)
        e.T = w.clips[47]!!.frameCount(e.S) - 1
        e.U = w.clips[47]!!.frameDuration(e.S, e.T) - 1
        w.npcFsm.tickAx9(e, w, w.player)
        assertEquals(0, e.aB, "L34 zeroes aB")
        assertEquals(3, e.S, "L34 r() → i(3)")
    }

    @Test fun `S3 settle arm marks solid passive on anim end`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 300, 300, 3)
        e.T = w.clips[47]!!.frameCount(e.S) - 1
        e.U = w.clips[47]!!.frameDuration(e.S, e.T) - 1
        w.npcFsm.tickAx9(e, w, w.player)
        assertTrue(e.P and 32 != 0, "L38 → P|=32")
        assertTrue(e.P and 16 == 0, "L38 → P&=-17")
    }
}

// =====================================================================
// Slice 49 — ax15 bu() grapple volume (i.java:16693-16924, proven).
// =====================================================================

class Slice49Test {

    /** ax15 record (i.java:2669 → L362): `[15, aw, x, y, aE, S, P,
     *  az(r8[7]), z0(r8[8]), ...]` → `az=r8[7]`, Z-load `r8[8]/ak/al`. */
    private fun ax15At(w: Level0World, x: Int, y: Int, s: Int,
                       z7: Int = 0, z8: Int = -1): Entity {
        val e = Entity(15, w.clips[25])
        e.setPositionPx(x, y)
        val f = mutableListOf(15, 0, x, y, 0, s, 0, z7, z8)
        for (i in 9..15) f += 0
        w.npcFsm.initAx15(e, f, w)
        w.npcs.add(e)
        return e
    }

    private fun box(e: Entity, x0: Int, y0: Int, x1: Int, y1: Int) {
        e.W[0] = x0; e.W[1] = y0; e.W[2] = x1; e.W[3] = y1
    }

    private fun animEnd(e: Entity, w: Level0World) {
        e.T = w.clips[25]!!.frameCount(e.S) - 1
        e.U = w.clips[25]!!.frameDuration(e.S, e.T) - 1
    }


    @Test fun `init S9 arms the eight-slot Z with sentinel -1`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 9, z7 = 3, z8 = 42)
        assertEquals(3, e.az, "L362 az=r8[7]")
        assertEquals(-1, e.Z[4], "L362 Z[4]=-1 for S9")
        assertEquals(42, e.Z[0]); assertEquals(400, e.Z[1])
        assertEquals(700, e.Z[2]); assertEquals(0, e.Z[3])
        assertEquals(9, e.S)
    }

    @Test fun `init S6 keeps the four-slot Z`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 6, z8 = 7)
        assertEquals(0, e.Z[4], "S6 Z stays int[4] — no -1 sentinel")
        assertEquals(7, e.Z[0]); assertEquals(400, e.Z[1]); assertEquals(700, e.Z[2])
    }

    @Test fun `S9 tick only marks P16`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 9)
        w.npcFsm.tickAx15(e, w, w.player)
        assertTrue(e.P and 16 != 0, "L4 → P|=16")
        assertEquals(9, e.S)
    }

    @Test fun `clip25 leaves the S6 box empty like the original`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 6)
        assertEquals(e.ak, e.W[0]); assertEquals(e.al, e.W[1])
        assertEquals(e.W[0], e.W[2]); assertEquals(e.W[1], e.W[3])
    }

    @Test fun `S7 respawn arm returns the block to Z1-Z2 as S6`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 6)             // Z loaded at init
        e.setAnim(7)
        e.ak += 40; e.al += 30                    // moved off its home
        animEnd(e, w)
        w.npcFsm.tickAx15(e, w, w.player)
        assertEquals(6, e.S, "L202 → i(6) when Z[3]==0")
        assertEquals(400, e.ak); assertEquals(700, e.al)
        assertFalse(e in w.pendingRemove)
    }

    @Test fun `S7 with Z3 marked removes the entity`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 6)
        e.setAnim(7)
        e.Z[3] = 1
        animEnd(e, w)
        w.npcFsm.tickAx15(e, w, w.player)
        assertTrue(e in w.pendingRemove, "L203 → k.c(this)")
    }

    @Test fun `contact arms stay dormant on the empty S6 rect`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 6)
        val p = w.player
        p.setPositionPx(400, 700); p.refreshBoxes()
        p.S = 18; p.av = false                    // free anim, on the anchor
        w.npcFsm.tickAx15(e, w, w.player)
        assertNull(p.ga, "empty rect → no claim (clip25 ao spans 1:1)")
        assertEquals(18, p.S)
        assertEquals(6, e.S)
    }

    @Test fun `release frees an externally claimed player`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 400, 700, 6)
        val p = w.player
        p.setPositionPx(300, 400); p.refreshBoxes()
        p.S = 18; p.ga = e                        // e.g. a claim-script bind
        w.npcFsm.tickAx15(e, w, w.player)
        assertNull(p.ga, "L119 → g.a=null (point rect never overlaps)")
    }

    @Test fun `unsupported block falls at 4096 while grounded settles`() {
        val w = world(); w.npcs.clear()
        // anchor over two air cells (point-W probes under the anchor)
        var cx = -1; var cy = -1
        outer@ for (yy in 1 until w.level.rows - 1)
            for (xx in 1 until w.level.cols - 2) {
                val a = w.level.collisionCell(xx, yy)
                if (a < 12 && a != 5) { cx = xx; cy = yy; break@outer }
            }
        assertTrue(cx > 0, "fixture: found an air cell")
        val air = ax15At(w, cx * 20 + 10, cy * 20 + 10, 6)
        w.npcFsm.tickAx15(air, w, w.player)
        assertEquals(4096, air.ah, "L130 unsupported → ah=4096")
        // one solid cell (>=12 or ==5) beneath the anchor
        var sx = -1; var sy = -1
        outer@ for (yy in 1 until w.level.rows - 1)
            for (xx in 1 until w.level.cols - 1) {
                val a = w.level.collisionCell(xx, yy)
                if (a >= 12 || a == 5) { sx = xx; sy = yy; break@outer }
            }
        assertTrue(sx > 0, "fixture: found a solid cell")
        val grounded = ax15At(w, sx * 20 + 10, sy * 20 - 1, 6)
        w.npcFsm.tickAx15(grounded, w, w.player)
        assertTrue(grounded.bd, "L137 grounded → bd=true")
        assertEquals(0, grounded.ah)
    }

    @Test fun `ax66 mount snaps the anchor then unmounts same-tick`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 130, 135, 6)             // anchor inside platform box
        val m = Entity(66, null); m.setPositionPx(130, 140)
        box(m, 90, 130, 170, 160)
        w.npcs.add(m)
        w.npcFsm.tickAx15(e, w, w.player)
        assertEquals(131, e.al, "L167 mount → al=n.W[1]+1")
        assertNull(e.s,
            "L172: point-W never strict-overlaps → same-tick unmount")
    }

    @Test fun `S10 arms the real clip rect and sweeps hostiles`() {
        val w = world(); w.npcs.clear()
        val e = ax15At(w, 200, 200, 10)
        // proven bounds: clip25 rect0 = [-31,-50,57,51]
        assertEquals(200 - 31, e.W[0]); assertEquals(200 - 50, e.W[1])
        assertEquals(200 - 31 + 57, e.W[2]); assertEquals(200 - 50 + 51, e.W[3])
        e.ah = 512                                  // bt() requires ah!=0
        val n = Entity(11, null); n.setPositionPx(200, 175)
        box(n, 180, 160, 200, 180)
        n.aB = 0
        w.npcs.add(n)
        w.npcFsm.tickAx15(e, w, w.player)
        assertTrue(e.P and 16 != 0, "L5 → P|=16")
        assertEquals(0, n.S, "bt() → as() → ax11 i(0)")
    }
}

// =====================================================================
// Slice 50 — ax46 aZ() spring/trap (i.java:13568-13726, proven).
// =====================================================================

class Slice50Test {

    /** ax46 record (i.java:2700 → L206): `[46, aw, x, y, aE, S, P, az,
     *  z0(r8[8]), z1(r8[9]), clipIdx(r8[10]), pal(r8[11]), z7(r8[12])]`.
     *  `k.bl = {29, 0}` rebinds the anim clip by r8[10]. */
    private fun ax46At(w: Level0World, x: Int, y: Int, s: Int,
                       z0: Int = 0, z1: Int = 0, ci: Int = 0,
                       pal: Int = 0, z7: Int = 0): Entity {
        val e = Entity(46, w.clips[29])
        e.setPositionPx(x, y)
        val f = mutableListOf(46, 0, x, y, 0, s, 0, 0, z0, z1, ci, pal, z7)
        while (f.size < 16) f += 0
        w.npcFsm.initAx46(e, f, w)
        w.npcs.add(e)
        return e
    }

    @Test fun `init binds clip29 for bl-0 records and loads Z`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 0, z0 = 50, z1 = -40, pal = 2, z7 = 9)
        assertSame(w.clips[29], e.clip, "L15 aa = k.r(bl[0]) = clip29")
        assertEquals(0, e.S)
        assertEquals(50 shl 8, e.Z[0]); assertEquals(-40 shl 8, e.Z[1])
        assertEquals(30, e.Z[3]); assertEquals(0, e.Z[4])
        assertEquals(2, e.Z[5]); assertEquals(29, e.Z[6]); assertEquals(9, e.Z[7])
    }

    @Test fun `init binds clip0 for bl-1 armed records`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 2389, 386, 327, ci = 1, pal = 2)
        assertSame(w.clips[0], e.clip, "L15 aa = k.r(bl[1]) = clip0")
        assertEquals(327, e.S, "i(r8[5]) accepts 327 on the mega clip")
        assertEquals(327, e.Z[4], "armed marker Z[4]=r8[5]")
        assertEquals(0, e.Z[6])
    }

    @Test fun `head pins the palette to Z5 each tick`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 2, pal = 2)
        w.npcFsm.tickAx46(e, w, w.player)
        assertEquals(2, e.palette, "aa.l(Z[5])")
    }

    @Test fun `spring arm launches the falling player off the pad`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 0, z0 = 50, z1 = -40)
        // clip29 S0 rect = [-27,-12,53,8] → W = [173,388,226,396]
        assertEquals(173, e.W[0]); assertEquals(388, e.W[1])
        assertEquals(226, e.W[2]); assertEquals(396, e.W[3])
        val p = w.player
        p.setPositionPx(200, 390); p.refreshBoxes()
        p.S = 43; p.ah = 512                            // falling onto it
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(388, p.al, "op11 → al = pad top")
        assertEquals(200, p.ak, "op11 → ak = pad anchor")
        assertEquals(-40 shl 8, p.ah, "op11 → ah = Z[1]")
        assertEquals(50 shl 8, p.ag, "op11 → ag = Z[0]")
        assertEquals(22, p.S, "Z[0]!=0 → i(22)")
        assertFalse(p.av, "Z[0]>0 → av=false")
        assertEquals(1, e.S, "L88 → i(1) sprung")
    }

    @Test fun `spring ignores a rising player`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 0, z0 = 50, z1 = -40)
        val p = w.player
        p.setPositionPx(200, 390); p.refreshBoxes()
        p.S = 43; p.ah = -512                            // still moving up
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(43, p.S, "L82 ah<0 → no bounce")
        assertEquals(0, e.S)
    }

    @Test fun `S1 settle returns the pad to i0 on anim end`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 1)
        e.T = w.clips[29]!!.frameCount(1) - 1
        e.U = w.clips[29]!!.frameDuration(1, e.T) - 1
        w.npcFsm.tickAx46(e, w, w.player)
        assertEquals(0, e.S, "L71 → i(0)")
    }

    @Test fun `armed S327 pins the overlapping player via op24`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 327, ci = 1, pal = 2)
        assertTrue(e.X[2] > e.X[0], "clip0 S327 carries a real attack box")
        val p = w.player
        p.setPositionPx((e.X[0] + e.X[2]) / 2, (e.X[1] + e.X[3]) / 2)
        p.refreshBoxes(); p.S = 18
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(330, p.S, "aS.a(24,330) pins anim 330")
        assertEquals(e.W[0], p.ak, "L49 → ak = src.W[0]")
        assertEquals(e.W[1], p.al, "L49 → al = src.W[1]")
        assertEquals(0, p.ag); assertEquals(0, p.ah); assertEquals(0, p.aj)
        assertEquals(328, e.S, "L13 → i(328)")
    }

    @Test fun `S328 release throws the player off and rearms`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 328, ci = 1, pal = 2)
        val p = w.player
        p.setPositionPx((e.X[0] + e.X[2]) / 2, (e.X[1] + e.X[3]) / 2)
        p.refreshBoxes(); p.S = 330
        e.av = true
        e.T = w.clips[0]!!.frameCount(328) - 1
        e.U = w.clips[0]!!.frameDuration(328, e.T) - 1
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(329, e.S, "L46 → i(329)")
        assertEquals(165, p.S, "aS.i(165)")
        assertTrue(p.av, "aS.av = e.av")
        assertEquals(-2048, p.ag, "av → -2048")
        assertEquals(-5120, p.ah)
        assertEquals(30, e.Z[2], "L60 → Z[2]=Z[3]")
        // S329 → i(327) re-arm
        e.T = w.clips[0]!!.frameCount(329) - 1
        e.U = w.clips[0]!!.frameDuration(329, e.T) - 1
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(327, e.S, "L67 → i(327)")
    }

    @Test fun `unarmed touch throws the player off the trap`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 3)                    // Z[4]=3==S armed!
        // Z[4]==S here → this one is armed; spawn unarmed via record S
        val e2 = ax46At(w, 300, 400, 3)
        e2.Z[4] = 99                                    // disarm manually
        val p = w.player
        p.setPositionPx((e2.X[0] + e2.X[2]) / 2, (e2.X[1] + e2.X[3]) / 2)
        p.refreshBoxes(); p.S = 18
        w.npcFsm.tickAx46(e2, w, p)
        assertEquals(165, p.S, "L11 → aS.i(165)")
        assertEquals(if (e2.av) -2048 else 2048, p.ag)
        assertEquals(-5120, p.ah)
        assertEquals(7, e2.S, "L11 → i(7)")
    }

    @Test fun `S7 settles to the dead i2 arm`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 7)
        e.T = w.clips[29]!!.frameCount(7) - 1
        e.U = w.clips[29]!!.frameDuration(7, e.T) - 1
        w.npcFsm.tickAx46(e, w, w.player)
        assertEquals(2, e.S, "L63 → i(2)")
    }

    @Test fun `S10 pusher jets the player with record velocity`() {
        val w = world(); w.npcs.clear()
        val e = ax46At(w, 200, 400, 10, z0 = 30, z1 = -60)
        val p = w.player
        p.setPositionPx(e.W[0] + 2, e.W[1] + 2); p.refreshBoxes()
        p.S = 18
        e.av = false
        w.npcFsm.tickAx46(e, w, p)
        assertEquals(30 shl 8, p.ag, "L94 → ag = Z[0]")
        assertEquals(-60 shl 8, p.ah, "L94 → ah = Z[1]")
        assertTrue(p.av, "L98 → aS.av = !e.av")
        assertEquals(242, p.S, "L99 → aS.i(242)")
    }
}

// =====================================================================
// Slice 51 — ax7 ejection slot (i.java L88/L90/L94 :5110-5149, proven).
// =====================================================================

class Slice51Test {

    /** ax7 record: `[7, aw, x, y, aE, S, P, az(r8[7]), r8[8]]` — the
     *  slot has no Z; init stores `az` then `i(r8[5])+t()`. */
    private fun ax7At(w: Level0World, x: Int, y: Int, s: Int,
                      az: Int = 0, r8: Int = 1): Entity {
        val e = Entity(7, w.clips[60])
        e.setPositionPx(x, y)
        val f = mutableListOf(7, 0, x, y, 0, s, 0, az, r8)
        while (f.size < 16) f += 0
        w.npcFsm.initAx7(e, f, w)
        w.npcs.add(e)
        return e
    }

    @Test fun `init stores az and binds clip60`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 0, az = 1)
        assertSame(w.clips[60], e.clip, "bi[7]=60")
        assertEquals(0, e.S); assertEquals(1, e.az)
        assertTrue(e.W[2] > e.W[0], "clip60 S0 has a real box")
    }

    @Test fun `S0 swallows the overlapping player into the slot`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 0)
        e.av = false
        val p = w.player
        p.setPositionPx((e.W[0] + e.W[2]) / 2, (e.W[1] + e.W[3]) / 2)
        p.refreshBoxes(); p.S = 18; p.ah = 400; p.ag = -300
        w.npcFsm.tickAx7(e, w, p)
        assertEquals(1, e.S, "L90 → i(1)")
        assertEquals(313, p.S, "aS.i(313)")
        assertTrue(p.P and 64 != 0, "aS.P |= 64")
        assertEquals((e.W[0] + e.W[2]) shr 1, p.ak, "center snap x")
        assertEquals((e.W[1] + e.W[3]) shr 1, p.al, "center snap y")
        assertFalse(p.av, "aS.av = e.av")
        assertEquals(0, p.ah); assertEquals(0, p.ag)
        assertEquals(0, p.aj); assertEquals(0, p.ai)
    }

    @Test fun `S0 skips a player holding a marker`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 0)
        val p = w.player
        p.setPositionPx((e.W[0] + e.W[2]) / 2, (e.W[1] + e.W[3]) / 2)
        p.refreshBoxes(); p.S = 18
        // p.isHolding() == true: ci in front, |Δak|<120, |Δal|<20
        val c = Entity(14, null)
        c.setPositionPx(p.ak + 10, p.al)
        p.ci = c; p.av = false
        w.npcFsm.tickAx7(e, w, p)
        assertEquals(0, e.S, "L90 k.aS.f() gate → no swallow")
        assertEquals(18, p.S)
    }

    @Test fun `S1 holds the player center-synced then ejects`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 1)
        e.av = true
        val p = w.player
        p.setPositionPx(500, 500); p.refreshBoxes(); p.S = 313
        // mid-anim: still held
        e.T = 0; e.U = 0
        w.npcFsm.tickAx7(e, w, p)
        assertEquals((e.W[0] + e.W[2]) shr 1, p.ak, "L94 re-snap each tick")
        assertEquals((e.W[1] + e.W[3]) shr 1, p.al)
        assertEquals(e.T, p.T, "aS.T = this.T frame-sync")
        assertTrue(p.P and 64 != 0)
        assertEquals(1, e.S, "r()==false → still swallowing")
        // anim end: eject
        e.T = w.clips[60]!!.frameCount(1) - 1
        e.U = w.clips[60]!!.frameDuration(1, e.T) - 1
        w.npcFsm.tickAx7(e, w, p)
        assertEquals(0, e.S, "L94 r() → i(0)")
        assertEquals(-2048, p.ag, "av → -2048 eject")
    }

    @Test fun `S1 ejects rightward when the slot faces left-off`() {
        val w = world(); w.npcs.clear()
        val e = ax7At(w, 1397, 506, 1)
        e.av = false
        e.T = w.clips[60]!!.frameCount(1) - 1
        e.U = w.clips[60]!!.frameDuration(1, e.T) - 1
        w.npcFsm.tickAx7(e, w, w.player)
        assertEquals(2048, w.player.ag, "av=false → +2048")
    }
}


// ===========================================================================
// Slice 52 — ax72/ax78 counterweight pair + ax79 palette prop
// (init L384/L153/L386; ax78 `bA()` i.java:17525)
// ===========================================================================
class Slice52Test {

    private fun ax72At(w: Level0World, x: Int, y: Int, s: Int,
                       az: Int = 0, partnerAw: Int = -1,
                       drop: Int = 0): Entity {
        val e = Entity(72, w.clips[51])
        e.setPositionPx(x, y)
        val f = mutableListOf(72, 0, x, y, 0, s, 0, az, 10, drop, 20, 30, partnerAw)
        while (f.size < 16) f += 0
        w.npcFsm.initAx72(e, f, w)
        w.npcs.add(e)
        return e
    }

    private fun ax78At(w: Level0World, x: Int, y: Int, s: Int,
                       az: Int = 0): Entity {
        val e = Entity(78, w.clips[63])
        e.setPositionPx(x, y)
        val f = mutableListOf(78, 0, x, y, 0, s, 0, az)
        while (f.size < 16) f += 0
        w.npcFsm.initAx78(e, f, w)
        w.npcs.add(e)
        return e
    }

    private fun ax79At(w: Level0World, x: Int, y: Int, s: Int,
                       palette: Int = 0): Entity {
        val e = Entity(79, w.clips[0])
        e.setPositionPx(x, y)
        val f = mutableListOf(79, 0, x, y, 0, s, 0, palette, 77)
        while (f.size < 16) f += 0
        w.npcFsm.initAx79(e, f, w)
        w.npcs.add(e)
        return e
    }

    /** first support cell (h(): v<12 ? v>=5 : true) in the fixture grid */
    private fun supportCell(w: Level0World): Pair<Int, Int> {
        for (cy in 1 until w.level.worldH / 20)
            for (cx in 1 until w.level.worldW / 20)
                if (w.collisionCell(cx, cy) >= 5) return cx to cy
        error("no support cell in fixture")
    }

    /** first non-support cell (v<5) with a support cell directly below it */
    private fun airAboveSupport(w: Level0World): Pair<Int, Int> {
        for (cy in 1 until w.level.worldH / 20 - 1)
            for (cx in 1 until w.level.worldW / 20)
                if (w.collisionCell(cx, cy) < 5 && w.collisionCell(cx, cy + 1) >= 5)
                    return cx to cy
        error("no air-above-support column in fixture")
    }

    @Test fun `ax72 init stores the partner link and fixed drop offset`() {
        val w = world(); w.npcs.clear()
        val e = ax72At(w, 2897, 445, 0, az = 3, partnerAw = 34, drop = 7)
        assertSame(w.clips[51], e.clip, "bi[72]=51")
        assertEquals(3, e.az, "L384 az=r8[7]")
        assertEquals(10, e.Z[0]); assertEquals(7 shl 8, e.Z[1], "Z[1]=r8[9]<<8")
        assertEquals(20, e.Z[2]); assertEquals(30, e.Z[3])
        assertEquals(34, e.Z[4], "Z[4]=r8[12] — linked ax78's aw")
        assertEquals(0, e.S)
    }

    @Test fun `ax78 init then S0 settles +2 until supported then arms`() {
        val w = world(); w.npcs.clear()
        val (cx, cy) = supportCell(w)
        // probe (al+10)/20 hits cy: place the weight 10px above the support row
        val e = ax78At(w, cx * 20, cy * 20 - 10, 0, az = 2)
        assertSame(w.clips[63], e.clip, "bi[78]=63")
        assertEquals(2, e.az)
        w.npcFsm.tickAx78(e, w, w.player)
        assertEquals(1, e.S, "L5/L8 supported → i(1)")
        // drop back to S0 on air: +2 settle each tick, stays S0
        val (ax, ay) = airAboveSupport(w)
        val e2 = ax78At(w, ax * 20, ay * 20 - 10, 0)
        val before = e2.al
        w.npcFsm.tickAx78(e2, w, w.player)
        assertEquals(0, e2.S, "unsupported → keep settling")
        assertEquals(before + 2, e2.al, "L8 al+=2")
    }

    @Test fun `ax78 S1 holds on support, drops to S2 when unsupported`() {
        val w = world(); w.npcs.clear()
        val (cx, cy) = supportCell(w)
        val e = ax78At(w, cx * 20, cy * 20 - 10, 1)
        w.npcFsm.tickAx78(e, w, w.player)
        assertEquals(1, e.S, "L11 supported → hold")
        val (ax, ay) = airAboveSupport(w)
        val e2 = ax78At(w, ax * 20, ay * 20 - 10, 1)
        w.npcFsm.tickAx78(e2, w, w.player)
        assertEquals(2, e2.S, "unsupported → i(2)")
        assertEquals(1536, e2.aj, "fall gravity aj=1536")
    }

    @Test fun `ax78 S2 whooshes at T4U0 then lands into S3 zeroed`() {
        val w = world(); w.npcs.clear()
        val (cx, cy) = supportCell(w)
        val e = ax78At(w, cx * 20, cy * 20 - 10, 2)
        e.T = 4; e.U = 0; e.ah = 2048; e.aj = 0
        w.sfxLog.clear()
        w.npcFsm.tickAx78(e, w, w.player)
        assertTrue(14 in w.sfxLog, "T==4&&U==0 → k.A(14) whoosh")
        assertEquals(3, e.S, "supported → i(3)")
        assertEquals(0, e.aj); assertEquals(0, e.ah, "landed velocity zeroed")
    }

    @Test fun `ax78 S2 keeps falling on air and S3 sweeps + re-drops`() {
        val w = world(); w.npcs.clear()
        val (ax, ay) = airAboveSupport(w)
        val e = ax78At(w, ax * 20, ay * 20 - 10, 2)
        e.T = 0; e.U = 0
        w.npcFsm.tickAx78(e, w, w.player)
        assertEquals(2, e.S, "still falling")
        assertEquals(1536, e.aj)
        // S3 on support: settle path keeps S3 and zeroes vel; on air aj=1536
        val (cx, cy) = supportCell(w)
        val e3 = ax78At(w, cx * 20, cy * 20 - 10, 3)
        e3.ah = 1024
        w.npcFsm.tickAx78(e3, w, w.player)
        assertEquals(3, e3.S); assertEquals(0, e3.ah); assertEquals(0, e3.aj)
        val e4 = ax78At(w, ax * 20, ay * 20 - 10, 3)
        w.npcFsm.tickAx78(e4, w, w.player)
        assertEquals(1536, e4.aj, "L28 air → gravity again")
    }

    @Test fun `ax79 init pins the palette slot`() {
        val w = world(); w.npcs.clear()
        val e = ax79At(w, 6456, 510, 79, palette = 2)
        assertSame(w.clips[0], e.clip, "bi[79]=0")
        assertEquals(2, e.palette, "L386 e.palette = Z[0] = r8[7]")
        assertEquals(2, e.Z[0]); assertEquals(77, e.Z[1])
        assertEquals(79, e.S, "S = r8[5] verbatim (record legitimately uses 79)")
    }

    @Test fun `level0 counterweight records link by aw`() {
        val w = world()
        val lever = w.npcs.find { it.ax == 72 && it.aw == 33 }
        val weight = w.findByAw(34)
        assertNotNull(lever); assertNotNull(weight)
        assertEquals(34, lever!!.Z[4], "ax72 uid33 → ax78 uid34")
        assertEquals(78, weight!!.ax)
    }
}

class Slice53Test {

    /** ax80 record helper: f = {80, uid, x, y, 0, S, 0, az, ...} — init reads
     *  r8[7] only (L389 :2734→ :3636, proven); clip is always null because
     *  pack-3 has no entry-057 (bi[80]=57 → J(57)=null). */
    private fun ax80At(w: Level0World, x: Int, y: Int, s: Int,
                       az: Int = 0): Entity {
        val e = Entity(80, w.clips[57])
        e.setPositionPx(x, y)
