        e.W[2] = p.X[2] + 2; e.W[3] = p.X[3] + 2         // W fully covers X
        w.npcFsm.tickAx58(e, w, p)
        assertEquals(3, e.S, "W∩aS.X && aS.S!=22 -> i(3)")
