class Slice60Test {
    private fun ax60At(w: Level0World, x: Int, y: Int, vararg f: Int): Entity {
        val e = Entity(60, w.clips[21])
        val rec = mutableListOf(60, 1, x, y)
        rec += f.toList()
        while (rec.size < 22) rec += 0
        e.setPositionPx(x, y)
        w.npcFsm.initAx60(e, rec.toList(), w)
        w.npcs.add(e)
        keepLive(e)
        return e
    }

    @Test fun `init S9 lift — P4096, Z3=al, Z5 probed, auto-bounce`() {
        val w = world()
        val e = ax60At(w, 100, 200, 5, 9, 0, -1, 40, 1)
        assertTrue(e.P and 4096 != 0, "P|=4096 for S9")
        assertEquals(200, e.Z[3], "Z[3]=al for S9")
        assertEquals(1, e.az)
        assertEquals(2, e.Z[4], "r8[9]==1 → auto-bounce")
        assertTrue(e.Z[5] <= 200, "Z[5] bound probed ≤ spawn al")
        assertEquals(9, e.S, "init tail i(r8[5])")
    }

    @Test fun `init S13 pair member — az=0, P16, aC=Z2`() {
        val w = world()
        val e = ax60At(w, 100, 200, 4, 13, 0, 58, 0, 0)
        assertEquals(0, e.az, "az=0 for S13")
        assertTrue(e.P and 16 != 0, "P|=16")
        assertEquals(13, e.S)
    }

    @Test fun `S9 arm resolves ax58 link → Z4=3 lever mode`() {
        val w = world()
        settleIntro(w)                 // I() L108 gate: tests run post-intro
        val lever = Entity(58, w.clips[20]); lever.aw = 88888
        w.npcs.add(lever)
        val e = ax60At(w, 100, 200, 5, 9, 0, 88888, 40, 0)
        w.tick(emptyList())
        assertSame(lever, e.s, "s = ax58 link")
        assertEquals(3, e.Z[4], "Z[4]=3")
    }

    @Test fun `S9 arm missing link → i(10) travel + Z0=-1`() {
        val w = world()
        settleIntro(w)                 // I() L108 gate: tests run post-intro
        val e = ax60At(w, 100, 200, 5, 9, 0, 999999, 40, 0)
        w.tick(emptyList())
        assertEquals(10, e.S, "i(10)")
        assertEquals(-1, e.Z[0])
        assertEquals(39, e.aC, "aC=Z[2] set by arm, then L149 decrements same tick")
    }

    @Test fun `ride — standing player on moving lift gets S50`() {
        val w = world()
        val e = ax60At(w, 100, 200, 5, 10, 0, -1, 40, 0)   // S10 vertical mover
        e.refreshBoxes()
        // player's box straddles the lift's bottom edge (W[1]≤W[3]≤W[3])
        w.player.setPositionPx((e.W[0] + e.W[2]) shr 1, e.W[3])
        w.player.refreshBoxes()
        w.player.aZ = true
        e.ah = 256                                         // moving down
        w.npcFsm.tickAx60(e, w, w.player)
        assertEquals(50, w.player.S, "moving lift → ride crouch S50")
    }

    @Test fun `auto-bounce Z4=2 — solid probe reverses ah`() {
        val w = world()
        val e = ax60At(w, 100, 200, -3, 10, 0, -1, 40, 1)  // Z[4]=2
        e.refreshBoxes()
        e.ah = -256                                        // moving up
        w.npcFsm.tickAx60(e, w, w.player)
        assertTrue(e.ah != 0)
    }

    @Test fun `lever Z4=3 bf() → travel anim + ah`() {
        val w = world()
        val lever = Entity(58, w.clips[20]); lever.aw = 88888
        lever.S = 10                                       // bf() set member
        w.npcs.add(lever)
        val e = ax60At(w, 100, 200, 5, 9, 0, 88888, 40, 0)
        w.tick(emptyList())                                // binds s, Z4=3
        lever.S = 10                                       // bf() set member
        w.npcFsm.tickAx60(e, w, w.player)                  // L94: bf → move
        assertEquals(10, e.S, "i(10) travel")
        assertTrue(e.runnerBz, "bz moving")
        assertTrue(e.ah > 0, "ah = +Z[1]<<8 downward")
    }

    @Test fun `lever Z4=3 idle lever + latch → unlatch reverse`() {
        val w = world()
        settleIntro(w)                 // I() L108 gate: tests run post-intro
        val lever = Entity(58, w.clips[20]); lever.aw = 88888
        lever.S = 0                                        // not bf()
        w.npcs.add(lever)
        val e = ax60At(w, 100, 200, 5, 9, 0, 88888, 40, 0)
        w.tick(emptyList()); w.tick(emptyList())
        e.k = true                                         // latched
        w.tick(emptyList())
        assertFalse(e.k, "unlatched on idle lever")
        assertTrue(e.ah < 0, "reverse velocity")
    }

    @Test fun `mount — gB player inside S13 box → ga bind + carry`() {
        val w = world()
        // clip21 anim13 W=(0,-36,22,36): box above the anchor; W[0]=Z[5]
        // stretches the left edge to the bound. c(true) runs for S∈{13,15}.
        val e = ax60At(w, 100, 200, 4, 13, 0, -1, 0, 0)
        e.refreshBoxes()
        w.player.setPositionPx((e.W[0] + e.W[2]) shr 1, (e.W[1] + e.W[3]) shr 1)
        w.player.setAnim(19)                               // gB member
        w.player.refreshBoxes()
        assertTrue(Entity.overlapStrict(w.player.W, e.W), "fixture overlap")
        w.npcFsm.tickAx60(e, w, w.player)
        assertSame(e, w.player.ga, "g.a = platform")
        val before = w.player.ak
        e.ag = 1280
        w.npcFsm.tickAx60(e, w, w.player)
        assertTrue(w.player.ak > before, "ride-carry ak += ag>>8")
    }

    @Test fun `S13 pair handoff — X overlap swaps velocity`() {
        val w = world()
        // clip21 anim13 X=(17,-36,16,36) right-extended; anim11
        // X=(-11,-36,16,36) left-extended. Pair parked just left of e's
        // right box ��� the L92 swap fires.
        val pair = ax60At(w, 115, 200, 4, 11, 0, -1, 0, 0) // S11 member
        val e = ax60At(w, 100, 200, 4, 13, 0, -1, 0, 0)
        e.ag = 1024
        w.npcFsm.tickAx60(e, w, w.player)
        assertEquals(1024, pair.ag, "pair gets Z[1]<<8 push")
        assertEquals(-1024, e.ag, "self reverses")
    }

    @Test fun `zone scan — ax10 S39 overlap latches k for Z4=3`() {
        val w = world()
        val zone = Entity(10, w.clips[10]); zone.S = 39
        w.npcs.add(zone)
        val e = ax60At(w, 100, 200, 5, 10, 0, -1, 0, 0)
        e.Z[4] = 3
        e.refreshBoxes()
        // zone inside the lift's real W corridor
        zone.W[0] = e.W[0] + 1; zone.W[1] = e.W[1] + 1
        zone.W[2] = e.W[2] - 1; zone.W[3] = e.W[3] - 1
        w.npcFsm.tickAx60(e, w, w.player)
        assertTrue(e.k, "S10 + Z[4]==3 + zone → latch k")
    }
}


class Slice69Test {
    private fun ax69At(w: Level0World, x: Int, y: Int, vararg f: Int): Entity {
        val e = Entity(69, w.clips[38])
        val rec = mutableListOf(69, 152, x, y)
        rec += f.toList()
        while (rec.size < 22) rec += 0
        e.setPositionPx(x, y)
        w.npcFsm.initAx69(e, rec.toList(), w)
        w.npcs.add(e)
        return e
    }

    private fun ax11At(w: Level0World, x: Int, y: Int, aw: Int): Entity {
        val e = Entity(11, w.clips[7])
        e.aw = aw
        e.setPositionPx(x, y)
        e.refreshBoxes()
        w.npcs.add(e)
        return e
    }

    /** clip38 W = (-38,-75,76,76) rel anchor → arithmetic-shift floor at
     *  (100,200): x∈[61,137], y∈[124,200], mid-x=99, mid-y=162. */
    private fun finish(e: Entity) {
        val c = e.clip!!
        e.T = c.frameCount(e.S) - 1
        e.U = c.frameDuration(e.S, e.T) - 1
    }

    @Test fun `init — Z0=f4 flavor, Z1=f7 link, S=f5, az=0 aA=0`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, 102)
        assertEquals(1, e.Z[0], "Z[0] = r8[4] zone flavor")
        assertEquals(102, e.Z[1], "Z[1] = r8[7] link uid")
        assertEquals(0, e.S, "S = r8[5] init anim")
        assertEquals(0, e.az); assertEquals(0, e.aA)
    }

    @Test fun `S0 Z0=0 — gB player inside zone hangs S250, e S7, af=link`() {
        val w = world()
        // uid 9999 — free of every shipped record (level-0 carries a
        // checkpoint at aw=102 which now spawns after the clipless gate
        // removal; k.q resolves record entities before test fixtures).
        val victim = ax11At(w, 160, 190, 9999)
        val e = ax69At(w, 100, 200, 0, 0, 0, 9999)
        w.player.setPositionPx(100, 163)
        w.player.setAnim(19)                              // gB member
        w.player.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(250, w.player.S, "player hangs")
        assertEquals(7, e.S, "zone arms")
        assertSame(victim, e.af, "af = k.q(Z[1]) link")
        assertSame(e, w.player.af, "player bound to zone")
        assertEquals(99, w.player.ak); assertEquals(162, w.player.al)
        assertEquals(0, w.player.ag)
    }

    @Test fun `S0 Z0=0 — non-gB player does not bind`() {
        val w = world()
        val e = ax69At(w, 100, 200, 0, 0, 0, -1)
        w.player.setPositionPx(100, 163)
        w.player.setAnim(0)                               // not in gB set
        w.player.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertNotEquals(250, w.player.S)
        assertEquals(0, e.S)
    }

    @Test fun `S0 Z0=1 — feet must hang below zone mid to perch`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, -1)
        w.player.setAnim(19)
        // W[3] (foot edge) above the midline → rejected (L65)
        w.player.setPositionPx(100, 130)
        w.player.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(0, e.S, "feet above mid: no bind")
        w.player.setPositionPx(100, 195)
        w.player.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(1, e.S, "feet below mid: perch anim S1")
        assertSame(e, w.player.af)
    }

    @Test fun `preamble — ax11 victim right of zone within 40px binds + marker`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, -1)
        e.setAnim(7)
        w.player.af = e                                   // bound player
        w.player.setPositionPx(100, 163)
        val victim = ax11At(w, 160, 190, 7)
        victim.av = false                                 // facing right = away
        victim.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertSame(victim, e.af, "victim bound")
        assertNotNull(e.ae, "hand marker spawned")
        assertEquals(152, e.ae!!.ak); assertEquals(115, e.ae!!.al)
    }

    @Test fun `preamble — victim facing the player is skipped`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, -1)
        e.setAnim(7)
        w.player.af = e
        w.player.setPositionPx(100, 163)
        val victim = ax11At(w, 160, 190, 7)
        victim.av = true                                  // facing left = toward player
        victim.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertNull(e.af, "facing victim rejected (!g(aS))")
    }

    @Test fun `preamble keep-alive — victim drifting past 40px releases af`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, -1)
        e.setAnim(7)
        w.player.af = e
        w.player.setPositionPx(100, 163)
        val victim = ax11At(w, 160, 190, 7)
        victim.av = false; victim.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertSame(victim, e.af)
        victim.setPositionPx(250, 190); victim.refreshBoxes()   // >40px out
        w.npcFsm.tickAx69(e, w, w.player)
        assertNull(e.af, "out-of-reach victim dropped (L39)")
    }

    @Test fun `S7 kill arm — eligible victim + v(65568) → leap, death anim`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, -1)            // Z0=1 auto-eligible
        e.setAnim(7)
        w.player.af = e
        w.player.setPositionPx(100, 163)
        val victim = ax11At(w, 160, 190, 7)
        victim.av = false; victim.refreshBoxes()
        w.pad.commit(65568)                               // v() edge
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(244, w.player.S, "aS.i(244) leap")
        assertTrue(w.player.P and 64 != 0, "P|=64")
        assertEquals(162, w.player.al); assertEquals(137, w.player.ak,
            "player snaps to zone right-center")
        assertEquals(117, victim.S, "af.i(117) death anim")
        assertEquals(-1, victim.az)
        assertEquals(2, e.S, "i(2) kill windup")
    }

    @Test fun `S7 kill arm — Z0=0 requires prompt eligibility`() {
        val w = world()
        val e = ax69At(w, 100, 200, 0, 0, 0, -1)            // Z0=0 prompt mode
        e.setAnim(7)
        w.player.af = e
        w.player.setPositionPx(100, 163)
        // victim inside 40px reach but FACING the player → not eligible
        val victim = ax11At(w, 160, 190, 7)
        victim.av = true; victim.refreshBoxes()
        e.af = victim                                     // bound by link
        w.pad.commit(65568)
        w.npcFsm.tickAx69(e, w, w.player)
        assertNotEquals(244, w.player.S, "facing victim blocks the kill")
    }

    @Test fun `S2 censored tail — kBK=false → S10 + player recentered`() {
        val w = world()
        val e = ax69At(w, 100, 200, 0, 0, 0, -1)
        e.setAnim(2); finish(e)
        w.player.setPositionPx(90, 163)
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(10, e.S, "censored chain 2→10")
        assertEquals(99, w.player.ak, "player recentered on zone")
    }

    @Test fun `S4 kill-landing — p S244 → S12 + settle + af release`() {
        val w = world()
        val e = ax69At(w, 100, 200, 0, 0, 0, -1)            // Z0=0
        e.setAnim(4); e.aA = 0; finish(e)
        w.player.setAnim(244); w.player.P = w.player.P or 64
        w.player.af = e
        w.player.setPositionPx(100, 163)
        w.player.refreshBoxes()
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(12, e.S, "censored landing 4→12")
        assertEquals(0, w.player.S, "aS.i(0)")
        assertTrue(w.player.P and 64 == 0, "P&=-65")
        assertNull(w.player.af)
    }

    @Test fun `S4 aA==1 mission advance — bw=-1 bx=57 screenL(13)`() {
        val w = world()
        val e = ax69At(w, 100, 200, 0, 0, 0, -1)
        e.setAnim(4); e.aA = 1; finish(e)
        w.player.af = e
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(-1, w.kBw, "k.bw = -1")
        assertEquals(57, w.kBx, "k.bx = 57")
    }

    @Test fun `S6 carry-drift — u(8256) drifts both, w(12368) release → S7`() {
        val w = world()
        val e = ax69At(w, 100, 200, 1, 0, 0, -1)
        e.setAnim(6)
        w.player.af = e
        w.player.setPositionPx(100, 163)
        w.pad.commit(8256)                                // RIGHT held
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(1536, e.ag); assertEquals(1536, w.player.ag)
        w.pad.commit(0)                                   // released → eM edge
        w.npcFsm.tickAx69(e, w, w.player)
        assertEquals(7, e.S, "release → i(7) re-arm")
        assertEquals(0, e.ag); assertEquals(0, w.player.ag)
    }
}

