    }

    @Test fun `S0 — waypoint crawl dominant axis at pace Z1 shl 8`() {
        val w = world()
        val e = ax64At(w, 100, 100, anim = 0,
            z = listOf(0, 0, 500))              // Z[2] = waypoint uid
        wp(w, 500, 300, 100)
        w.player.setPositionPx(900, 900)
        w.pad.commit(0)
