        val w = openStats(world())
        w.kAu = 1                                    // difficulty mid
        w.kAp[0] = 10; w.kAp[3] = 5; w.kAp[1] = 2; w.kAp[5] = 3
        repeat(26) { w.tick(emptyList()) }           // panel cap + jG>10
        // base 0 (aj<7) + 10*200 + 5*200 - 2*300 + 3*30 = 2490
        assertEquals(2490, w.statsScore)
