class Slice97Test {
    private fun bh3World(): Level0World {
        val w = world(); w.npcs.clear(); w.kAj = 1         // bh[1]==3
        w.stateL(8)                                      // pin play state
        return w
    }

    @Test fun `bh3 boss column clamps aB to bU`() {
        val w = bh3World()
        val boss = Entity(29, w.clips[7]); w.kB = boss
        w.iBT = true; w.iBU = 120
        boss.aB = 300
        w.tick(emptyList())
        assertEquals(120, boss.aB, "B.aB > i.bU → clamp (k.java:4191)")
    }

    @Test fun `bh3 ap4 floor clamp`() {
        val w = bh3World()
        w.kAp[4] = -3
        w.tick(emptyList())
        assertEquals(0, w.kAp[4], "ap[4]<0 → 0 (k.java:4204)")
    }

    private fun tickClean(w: Level0World, n: Int) {
        // keep hudStep ungated: no claim overlay, no script spawns, and
        // the player inside the autoscroll camera (al > camY+240 → l(12)
        // freezes the tick before hudStep runs)
        repeat(n) {
            w.kC = null; w.pendingInsert.clear()
            w.player.al = w.camY + 100
            w.tick(emptyList())
        }
    }

    @Test fun `alert meter aH countdown slides then poisons`() {
        val w = bh3World()
        w.kAE = 50; w.kAH = 80; w.kAF = 0
        tickClean(w, 50)                        // 80→30
        assertEquals(30, w.kAH, "aH>30 → aH-- only")
        assertEquals(0, w.alertSlide, "aH>30 → i3=0 (icon in place)")
        tickClean(w, 30)                        // 30→0, slide grows
        assertEquals(30, w.alertSlide)
        tickClean(w, 1)                         // aH→-1 → aE=aH, return
        assertEquals(-1, w.kAE, "aE = aH(-1) poisons the meter (k.java:4216)")
        assertEquals(0, w.kAH)
        tickClean(w, 1)
        // slice 180: n() runs now — `aE<0 → aE=0` (g.java:5621) eats the
        // poison value; with aH==0 the stall gate stays closed.
        assertEquals(0, w.kAE, "n() clamps the poisoned aE back to 0")
    }

    @Test fun `alert meter aF trickle`() {
        val w = bh3World()
        w.kAE = 50; w.kAH = -1; w.kAF = 7
        tickClean(w, 1)
        // slice 180: n()'s aG decay divider (kAG=0 → -1 → reset+aE--) also
        // runs: -1 + +3 → 52. Subsequent ticks decay only every 6th.
        assertEquals(52, w.kAE, "aE-- divider + aF trickle +3")
        assertEquals(4, w.kAF)
        tickClean(w, 1)
        assertEquals(55, w.kAE)
        tickClean(w, 1)
        assertEquals(56, w.kAE, "remainder <3 → aE += aF")
        assertEquals(0, w.kAF)
        assertEquals(56, w.alertFill, "i4 = min(aE,100)")
    }

    @Test fun `alertFill caps at 100`() {
        val w = bh3World()
        w.kAE = 140; w.kAH = -1; w.kAF = 0
        tickClean(w, 1)
        assertEquals(100, w.alertFill)
    }

    @Test fun `g-g overhead gate`() {
        val w = world(); w.npcs.clear()
        val p = w.player
        // no focus entity → arm skipped (renderer-side; here verify fields)
        p.S = 303; p.K = 2; p.gQL = 150; p.gQM = 90
        assertNull(p.g)
        p.g = Entity(11, w.clips[7])
        assertEquals(303, p.S)
        assertEquals(2, p.K, "aS.K = anim frame (k.java:4347)")
    }
}

class Slice98Test {
    private fun tickClean(w: Level0World, n: Int) {
        repeat(n) {
            w.kC = null; w.pendingInsert.clear()
            w.player.al = w.camY + 100
            w.tick(emptyList())
        }
    }

    @Test fun `fadeOut ramps nine stripes then one black frame`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.fadeOut()                                       // k.B(26)
        assertTrue(w.kAn); assertFalse(w.kAo)
        assertEquals(0, w.kBI); assertEquals(26, w.kFk)
        tickClean(w, 9)
        assertEquals(234, w.kBI, "bI += 26 x9 = 234")
        assertEquals(9, w.kFn, "fn grows one stripe per in-ramp step")
        assertTrue(w.kAn, "still fading — 234 <= 255-26 is false next tick")
        tickClean(w, 1)
        assertFalse(w.kAn, "bI>255-fk → an=false (k.java:3171)")
        assertTrue(w.fadeSolidFrame, "single solid-black frame armed")
    }

    @Test fun `fadeIn drains bI and recedes stripes`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.kFn = 9
        w.fadeIn()                                        // k.C(26)
        assertTrue(w.kAo); assertFalse(w.kAn)
        assertEquals(255, w.kBI)
        tickClean(w, 1)
        assertEquals(229, w.kBI); assertEquals(8, w.kFn)
        tickClean(w, 8)
        assertEquals(21, w.kBI); assertEquals(0, w.kFn)
        tickClean(w, 1)
        assertFalse(w.kAo, "bI<fk → ao=false (k.java:3185)")
        assertEquals(0, w.kFn, "fn untouched once ao clears")
    }

    @Test fun `fadeIn during fadeOut swaps arms`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.fadeOut()
        w.fadeIn()
        assertTrue(w.kAo); assertFalse(w.kAn); assertEquals(255, w.kBI)
    }

    @Test fun `vignette fs wraps at zero`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.iBh = 20                            // outlasts fs's 8-tick cycle
        tickClean(w, 1)
        assertEquals(70, w.kFs, "fs -= 10 (k.java:3193)")
        tickClean(w, 7)
        assertEquals(80, w.kFs, "fs<=0 → wrap to 80 (:3196)")
    }

    @Test fun `vignette gated off play state`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.iBh = 8; w.stateL(12)
        tickClean(w, 1)
        assertEquals(80, w.kFs, "j.c!=8 → fs frozen")
    }

    @Test fun `letterbox dz opens via av and chases aw`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.kDz = 0; w.kAv = true
        tickClean(w, 2)
        assertEquals(40, w.kDz, "av → dz += 20/tick (:3207)")
        w.kAv = false; w.kAw = 0
        tickClean(w, 2)
        assertEquals(0, w.kDz, "dz chases aw by -20")
        w.kAw = 55; w.kDz = 60
        tickClean(w, 1)
        assertEquals(55, w.kDz, "|diff|<20 → snap dz=aw")
        w.stateL(14)
        w.kAw = 0; w.kDz = 55
        tickClean(w, 1)
        assertEquals(55, w.kDz, "j.c==14 → letterbox frozen")
    }

    @Test fun `i-bJ flicker toggles bH to bI then zeroes with skip`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.iBJ = 1                                          // == i.bH
        tickClean(w, 1)
        assertEquals(2, w.iBJ, "bJ==bH && bL>=0 → bJ=bI (k.java:3227)")
        assertFalse(w.tailSkipFrame)
        tickClean(w, 1)
        assertEquals(0, w.iBJ, "bJ==bI && bL<=20 → bJ=0 (:3234)")
        assertTrue(w.tailSkipFrame, "early-return frame skips aU bar")
        tickClean(w, 1)
        assertFalse(w.tailSkipFrame, "latch is per-frame")
    }

    @Test fun `i-bJ bL negative holds bH`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        w.iBJ = 1; w.iBL = -5
        tickClean(w, 3)
        assertEquals(1, w.iBJ, "bL<0 → bH arm not taken")
    }

    @Test fun `kAU meter gate fields`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val q = Entity(61, w.clips[7]); w.kAU = q; w.iBy = 1
        q.P = q.P or 32
        // renderer gate `(P&32)==0 && iBy>0 && !tailSkipFrame` — world side
        assertEquals(32, q.P and 32, "P&32 clears the bar draw")
        q.P = q.P and 32.inv()
        assertEquals(0, q.P and 32)
        assertEquals(1, w.iBy)
    }
}

// ============================================================ slice 99
// ax10-S16 door-teleport: S16 arm (i.java:12326-12431) + bh()/bi()
// (i.java:14421/:14437) + i.a(iVar) bind (i.java:231). All proven.
class Slice99Test {
    /** Paired S16 doors: `door` W wraps the player, `dest` (aw=77) is
     *  the oId/Z[0] link target. `door.aD=1` so bi() faces right. */
    private fun doorPair(w: Level0World): Pair<Entity, Entity> {
        val dest = Entity(10, null).apply {
            aw = 77; S = 16
            ak = 920; al = 730
            W[0] = 900; W[1] = 700; W[2] = 940; W[3] = 760
            aD = 1
        }
        val door = Entity(10, null).apply {
            S = 16
            ak = w.player.ak; al = w.player.al
            W[0] = w.player.ak - 30; W[1] = w.player.al - 60
            W[2] = w.player.ak + 30; W[3] = w.player.al + 4
            oId = 77; Z[0] = 77
        }
        w.npcs.add(door); w.npcs.add(dest)
        return door to dest
    }

    @Test fun `door overlap marks the player with the 105 prompt`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.aZ = true; p.g = null; p.ga = null
        val (door, _) = doorPair(w)
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertNotNull(p.ae, "aS.a(105,…) spawned into player ae")
        assertEquals(105, p.ae!!.S, "marker anim 105")
        assertEquals(300, door.az, "az=300 marker TTL (L1784)")
        assertNull(p.ac, "no bind without the keypress")
    }

    @Test fun `door leave drops the door ae link`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.g = null; p.ga = null
        val (door, _) = doorPair(w)
        door.ae = Entity(14, null)                    // door-side ae link
        p.ak = door.W[2] + 200; p.refreshBoxes()       // out of the zone
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertNull(door.ae, "L1850 G() on no-overlap")
    }

    @Test fun `door exit tap binds player to dest and fades in`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.aZ = true; p.g = null; p.ga = null
        val (door, dest) = doorPair(w)
        w.pad.commit(16388)
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertSame(dest, p.ac, "bh() k.q(o) → aS.a(dest)")
        assertTrue(dest.P and 256 != 0, "bind marks P|=256")
        assertEquals((door.W[0] + door.W[2]) shr 1, p.ak,
            "player centered on exit door (bh :14428)")
        assertEquals(0, p.ag + p.ah + p.ai + p.aj, "velocity zeroed")
        assertEquals(284, p.S, "aS.i(284)")
        assertTrue(w.kAn && !w.kAo, "k.B(26) fade-in armed")
        assertEquals(0, w.kBI, "bI=0 at fade-in start")
    }

    @Test fun `door exit blocked by live interact target g`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.aZ = true; p.ga = null
        p.g = Entity(14, null)                          // g.g != null
        val (door, _) = doorPair(w)
        w.pad.commit(16388)
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertNull(p.ac, "L1850 → no bind while g.g lives")
        assertFalse(w.kAn, "no fade")
    }

    @Test fun `door exit blocked while grapple link lives`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.aZ = true; p.g = null
        p.ga = Entity(43, null)                          // g.a != null
        val (door, _) = doorPair(w)
        door.az = -5
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertEquals(-5, door.az, "L177d early return skips az=300")
        assertNull(p.ae)
    }

    @Test fun `door arrival places player at dest and fades out`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        val (door, dest) = doorPair(w)
        p.ac = dest                                       // bound to dest
        w.kAn = false; w.kAo = false                      // fades idle
        w.npcFsm.tickTrigger(dest, w, p, w.pad)
        assertEquals((dest.W[0] + dest.W[2]) shr 1, p.ak, "bottom-center x")
        assertEquals(dest.W[3], p.al, "al = W[3]")
        assertTrue(p.av, "av = (aD&1)!=0 → right")
        assertEquals(285, p.S, "aS.i(285) arrive anim")
        assertTrue(w.kAo && !w.kAn, "k.C(26) fade-out armed")
        assertEquals(255, w.kBI, "bI=255 at fade-out start")
        assertEquals(300, dest.az, "az=300 still armed each tick")
    }

    @Test fun `door bound mid-fade-out flings player and opens dest`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        val (door, dest) = doorPair(w)
        p.ac = door                                       // bound to EXIT
        w.kAo = true; w.kBI = 20                          // ao && bI>13
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertEquals(19, dest.S, "r8.i(19) dest open anim")
        assertEquals(43, p.S, "aS.a(0) → enterStateMasked(43,32) fling")
        assertEquals(1536, p.aj, "fling aj=1536")
    }

    @Test fun `door unbound mid-fade-in opens dest`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.aZ = false; p.g = null; p.ga = null
        val (door, dest) = doorPair(w)
        w.kAn = true; w.kBI = 20                          // an && bI>13
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertEquals(17, dest.S, "L1837 r8.i(17)")
        assertNull(p.ac, "no bind without the keypress")
    }

    @Test fun `door without o link does nothing unbound`() {
        val w = world(); w.npcs.clear(); w.stateL(8)
        val p = w.player
        p.refreshBoxes(); p.aZ = true; p.g = null; p.ga = null
        val (door, _) = doorPair(w)
        door.oId = -1
        w.pad.commit(16388)
        w.npcFsm.tickTrigger(door, w, p, w.pad)
        assertNull(p.ae, "o==-1 → L17d0 early return")
    }
}

// =========================================================================
// Slice 103 — jC==21 dialog render state (k.java:350-450, 899-1017):
// b(9,1+aj,str,str) load → bM[] 3-line pages + bN icon propagation,
// typewriter bR/bS/bT, u==9 press tail (reveal → dismiss, no page adv).
// =========================================================================
class Slice103Test {
    @Test fun `kDialog loads u-9 state and wraps pages at 300`() {
        val w = world()
        assertTrue(w.kDialog(5, 26, 1))
        assertEquals(9, w.dlgU)
        assertEquals(1, w.bO); assertEquals(5, w.bN0); assertEquals(5, w.dlgBN[0])
        assertTrue(w.dlgW >= 1)
        assertNotNull(w.dlgBM[0]); assertTrue(w.dlgBM[0]!!.isNotEmpty())
        assertEquals(0, w.dlgV); assertEquals(0, w.dlgBT)
        assertEquals(0, w.dlgBR); assertEquals(30, w.dlgBS); assertTrue(w.dlgBQ)
        // bN[i] propagates to every page slot (k.java:392-398, proven)
        for (i in 1 until w.dlgW) assertEquals(5, w.dlgBN[i])
    }

    @Test fun `kBMark is the verbatim k-b-IIII panel initializer`() {
        val w = world()
        assertFalse(w.kBMark(8, 1, -1, 0), "i3==-1 → false (:353)")
        // multi-row arm (u8): u=slot; per-row a(d,·,i!=6,i) expansion;
        // D(0); bQ; z()  (k.java:358-371, proven)
        assertTrue(w.kBMark(8, 1, 26, 26))
        assertEquals(8, w.dlgU)
        assertTrue(w.dlgW >= 1); assertEquals(0, w.dlgV)
        assertTrue(w.dlgBQ); assertEquals(30, w.dlgBS); assertEquals(0, w.dlgBT)
        assertNotNull(w.dlgBM[0])
        // single-text arm (kinds 0/4/5/7): a(d,0,false,i)+1 at 220px —
        // no bN digit writes (k.java:356-357, proven)
        val w2 = world()
        assertTrue(w2.kBMark(0, 1, 26, 26))
        assertEquals(0, w2.dlgU); assertTrue(w2.dlgW >= 1); assertTrue(w2.dlgBQ)
    }

    @Test fun `typewriter counts bT up then pins -1`() {
        val w = world()
        w.kDialog(1, 27, 0)
        val len = w.dlgBM[0]!!.length
        w.dlgTypeTick(len)
        assertEquals(1, w.dlgBR); assertEquals(30 / 16, w.dlgBT)   // (bR*bS)/16
        repeat(400) { w.dlgTypeTick(len) }
        assertEquals(-1, w.dlgBT)                                // A() done
        val after = w.dlgBR
        w.dlgTypeTick(len)
        assertEquals(after, w.dlgBR, "bT==-1 stops the counter")
    }

    @Test fun `typing press reveals and revealed press dismisses`() {
        val w = scriptedWorld(
            scriptBlock(0, 0, scriptGroup(0, op105(3, 42, 1))))
        val e = claimer(w)
        e.runClaimScript(w)
        assertTrue(w.dialogModal)
        w.autoDismissDialog = false
        w.kC = e
        w.pad.e(Pad.M_CONTEXT); w.tick(emptyList())
        assertTrue(w.dialogModal, "press while typing reveals only (:955)")
        assertEquals(-1, w.dlgBT)
        // the revealed press runs the shared advance arm `x=48; D(v+1)`
        // (bytecode 3604-3629 — u∈{1,2,3,6,9} all reach it); v 0→1=w
        // → `C.Z(); l(8)` on the same tick.
        w.pad.e(Pad.M_CONTEXT); w.tick(emptyList())
        assertFalse(w.dialogModal,
            "revealed press → D(v+1) → v==w → C.Z(); l(8) (:3604/:985-989)")
        assertFalse(e.cd[0], "C.Z() resumed the claim")
        assertEquals(0, w.pad.edge)
    }

    @Test fun `cd2 claimer + 131072 edge suppresses the dialog press`() {
        val w = world()
        w.kDialog(1, 18, 0)
        w.screenL(21)
        val e = Entity(5, null); e.cd[2] = true; w.kC = e
        w.pad.edge = 131072                      // v(131072) edge latched
        assertTrue(w.dlgSuppressed(), "(:946) — claim script eats the press")
        e.cd[2] = false
        assertFalse(w.dlgSuppressed())
    }
}

class Slice106Test {
    @Test fun `ax9 record with r8-5==0 binds kAV`() {
        val w = world()
        assertNotNull(w.kAV, "uid-108 ax9 (fields[5]==0) must bind kAV")
        assertEquals(108, w.kAV!!.aw)
        assertEquals(6177, w.kAV!!.ak)
    }

    @Test fun `armed Z0 fires screenL-13 while the goal is ahead`() {
        val w = world()
        repeat(30) { w.tick(emptyList()) }          // intro settles
        val g = w.kAV!!
        assertFalse(w.won)
        g.Z[0] = 1                                  // arg-op (37,1,4) arm
        w.tick(emptyList())
        // goal 6177 sits >200px past the camera right edge → w()==2 →
        // bx=56; l(13); bw=0 (k.java:3346-3350, proven). l() remaps 13→31
        // for the milestone variant — both latch `won`.
        assertTrue(w.jC == 13 || w.jC == 31, "expected the win screen")
        assertEquals(56, w.kBx)
        assertEquals(0, w.kBw)
        assertTrue(w.won)
    }

    @Test fun `goal in the 200px band pulses goalTicker on even ticks`() {
        val w = world()
        repeat(30) { w.tick(emptyList()) }
        val g = w.kAV!!
        g.Z[0] = 1
        // w()==1 → goalTicker = j.f%2 — blink parity (k.java:3328, proven)
        var seen = mutableSetOf<Boolean>()
        for (i in 0 until 6) {
            g.ak = w.camRect[2] + 100               // re-anchor: band vs live camera
            w.tick(emptyList())
            seen += w.goalTicker
            if (w.won) break
        }
        assertFalse(w.won, "band case must not win")
        assertEquals(setOf(true, false), seen,
            "ticker must alternate with tickIndex parity")
    }
}


// --------------------------------------------------------------- slice 107
// ax9 S4 hint-banner + S5 context pad (aV() L15b9/L15e8, i.java:12121-12171).
// op22 scripts arm anims {0..8} onto ax9 uids — S4/S5 are live script states.
class Slice107Test {

    private fun ax9At(w: Level0World, x: Int, y: Int, s: Int, aF: Int = 0): Entity {
        val e = Entity(9, w.clips[47])
        e.setPositionPx(x, y)
        val f = mutableListOf(9, 0, x, y, 0, s, 0, -1, 0)
        for (i in 9..15) f += 0
        w.npcFsm.initAx9(e, f, w)
        e.aF = aF
        w.npcs.add(e)
        return e
    }

    private fun boxAroundPlayer(w: Level0World, e: Entity) {
        val p = w.player; p.refreshBoxes()
        e.W[0] = p.W[0] - 10; e.W[1] = p.W[1] - 10
        e.W[2] = p.W[2] + 10; e.W[3] = p.W[3] + 10
    }

    @Test fun `S4 overlap shows the aF level string and holds aC=-1`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 0, 0, 4, aF = 3)
        boxAroundPlayer(w, e)
        w.npcFsm.tickAx9(e, w, w.player)
        assertEquals(w.levelString(1 + w.kAj, 3), w.kAB, "k.aB = d(1+aj, aF)")
        assertEquals(-1, w.kAC, "aC = -1 — banner holds while touching")
    }

    @Test fun `S4 leave clears the banner only when aC is out`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 0, 0, 4, aF = 3)
        boxAroundPlayer(w, e)
        w.npcFsm.tickAx9(e, w, w.player)
        // walk off: empty k.aC → the banner clears (L15dd aC<=0 arm)
        e.W[0] = -5000; e.W[1] = -5000; e.W[2] = -4000; e.W[3] = -4000
        w.npcFsm.tickAx9(e, w, w.player)
        assertNull(w.kAB, "aC<=0 + no overlap → aB = null")
        // re-show, then leave while the countdown is still live
        boxAroundPlayer(w, e)
        w.npcFsm.tickAx9(e, w, w.player)
        e.W[0] = -5000; e.W[1] = -5000; e.W[2] = -4000; e.W[3] = -4000
        w.kAC = 5                                     // countdown live
        w.npcFsm.tickAx9(e, w, w.player)
        assertNotNull(w.kAB, "aC>0 → L1ec7 = return, banner kept")
    }

    @Test fun `S5 overlap plus up press rises the player to S22`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 0, 0, 5)
        boxAroundPlayer(w, e)
        w.pad.commit(16388)                            // u(16388) held
        w.npcFsm.tickAx9(e, w, w.player)
        assertEquals(22, w.player.S, "u(16388) → aS.i(22)")
    }

    @Test fun `S5 directional tap matches facing — av uses u2 else u8`() {
        val w = world(); w.npcs.clear()
        val e = ax9At(w, 0, 0, 5)
        boxAroundPlayer(w, e)
        w.player.av = true
        w.pad.commit(2)                                // av → u(2)
        w.npcFsm.tickAx9(e, w, w.player)
        assertEquals(22, w.player.S)

        val w2 = world(); w2.npcs.clear()
        val e2 = ax9At(w2, 0, 0, 5)
        boxAroundPlayer(w2, e2)
        w2.player.av = false
        w2.pad.commit(8)                               // !av → u(8)
        w2.npcFsm.tickAx9(e2, w2, w2.player)
        assertEquals(22, w2.player.S)

        val w3 = world(); w3.npcs.clear()
        val e3 = ax9At(w3, 0, 0, 5)
        boxAroundPlayer(w3, e3)
        w3.pad.commit(0)                               // no press → no rise
        w3.npcFsm.tickAx9(e3, w3, w3.player)
        assertNotEquals(22, w3.player.S)
    }
}


// --------------------------------------------------------------- slice 108
// jC==18 title tick + jc23 boot sound-prompt confirm (k.a() cases 18/23,
// k.java:1146-1175,1310-1324). Completes the screen-state coverage for the
// boot flow — reachable via stateL(23)'s confirm arm or the title itself.
class Slice108Test {

    @Test fun `jc18 context press latches cS then exits to main menu`() {
        val w = world()
        w.stateL(18)
        assertEquals(18, w.jC)
        w.pad.queuePress(Pad.M_CONTEXT)      // v(65568) edge (:1156)
        w.tick(emptyList())
        assertTrue(w.kCS, "press → cS")
        assertEquals(100, w.kCT)
        w.pad.queuePress(0)
        w.tick(emptyList())                  // cS arm: cT-=10 → l(2)
        assertEquals(2, w.jC, "cS → l(2) → main menu")
        assertEquals(0, w.kCT)
    }

    @Test fun `jc18 play-area tap also confirms via k-j pointerStrip`() {
        val w = world()
        w.stateL(18)
        // j() (k.java:523) reads k.H/k.I — the last pointer RELEASE
        // point — so drive it via an UP event inside the play strip.
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.UP, 200, 100)))
        assertTrue(w.kCS, "tap → cS")
    }

    @Test fun `jc23 sound prompt YES arms audio flags and lands on title`() {
        val w = world()
        w.stateL(23)                          // boot sound prompt (l(23) arm)
        assertEquals(19, w.kEc)
        w.kBw = 0                             // YES selected (eA[3][0]=14)
        w.kBE = false; w.kBF = false          // pre-clear to observe the set
        w.pad.queuePress(327712)              // v(327712) confirm (:1311)
        w.tick(emptyList())
        assertTrue(w.kBE && w.kBF, "bw==0 → bE=bF=true")
        assertEquals(18, w.jC, "confirm → l(18)")
    }

    @Test fun `jc23 NO clears both audio flags before l-18`() {
        val w = world()
        w.stateL(23)
        w.kBw = 1                             // NO selected (eA[3][1]=15)
        w.pad.queuePress(327712)
        w.tick(emptyList())
        assertFalse(w.kBE); assertFalse(w.kBF)
        assertEquals(18, w.jC)
    }

    @Test fun `jc23 without confirm keeps running ae`() {
        val w = world()
        w.stateL(23)
        w.pad.queuePress(0)
        w.tick(emptyList())
        assertEquals(23, w.jC, "no confirm → ae() only, stays on jc23")
    }

    @Test fun `jc23 YES row tap surfaces bw to the L102 else — audio on`() {
        val w = world()
        w.stateL(23)
        w.kBE = false; w.kBF = false          // pre-clear to observe the set
        // panel d(93,120,214): YES row at (93,130,214,30) — the b() loop's
        // per-row `c()` hit arms `bw=i13` + `E(32)` (k.java:7699-7704) and
        // YES/NO's action lives in the dispatch else (menuItem has no
        // kEc==19 arm), so the tap must reach the else as `bw`.
        w.tick(listOf(
            InputQueue.Event(0, InputQueue.Type.DOWN, 150, 145),
            InputQueue.Event(1, InputQueue.Type.UP, 150, 145)))
        assertTrue(w.kBE && w.kBF, "YES row tap → bw=0 → bE=bF=true")
        assertEquals(18, w.jC, "confirm → l(18)")
    }

    @Test fun `jc23 YES row tap spanning two ticks still confirms on release`() {
        val w = world()
        w.stateL(23)
        w.kBE = false; w.kBF = false
        // A tap that releases on a later tick than its DOWN: the arm
        // must hit-test the release point on the UP tick as well.
        w.tick(listOf(InputQueue.Event(0, InputQueue.Type.DOWN, 150, 145)))
        w.tick(listOf(InputQueue.Event(1, InputQueue.Type.UP, 150, 145)))
        assertTrue(w.kBE && w.kBF, "YES row release → bw=0 → bE=bF=true")
        assertEquals(18, w.jC)
    }

    @Test fun `jc23 YES NO rows stack vertically — tap NO picks NO`() {
        val w = world()
        w.stateL(23)
        w.kBE = true; w.kBF = true            // pre-set to observe the clear
        // bv=3 → no col split: YES (93,130,214,30), NO (93,163,214,30).
        // Tap center of NO → bw=1 → audio off.
        w.tick(listOf(
            InputQueue.Event(0, InputQueue.Type.DOWN, 200, 178),
            InputQueue.Event(1, InputQueue.Type.UP, 200, 178)))
        assertFalse(w.kBE); assertFalse(w.kBF, "NO row → bw=1 → audio off")
        assertEquals(18, w.jC)
    }
}




// --------------------------------------------------------------- slice 109
// jC==0 boot R() driver — the `cu` sub-phase FSM (k.R(), k.java:3949-4100).
// Splash dwells (2×3000ms, pause-skippable), load frames, then the 5000ms
// loading screen → `l(23)`. Timers map wall-clock onto jG ticks (49/81).
class Slice109Test {

    @Test fun `boot advances cu through load frames then logo dwell`() {
        val w = world()
        w.stateL(0)
        assertEquals(0, w.jC); assertEquals(0, w.kCu)
        w.tick(emptyList())                  // cu0 → cu1 (du arm)
        assertEquals(1, w.kCu)
        w.tick(emptyList())                  // cu1 → cu2 (asset load)
        assertEquals(2, w.kCu)
    }

    @Test fun `logo dwell holds for 49 ticks then advances`() {
        val w = world()
        w.stateL(0)
        w.tick(emptyList()); w.tick(emptyList())      // now cu2, du=jG
        repeat(47) { w.tick(emptyList()) }            // elapsed 2..48
        assertEquals(2, w.kCu, "elapsed <49 ticks < 3000ms — dwelling")
        w.tick(emptyList())                           // elapsed hits 49
        assertEquals(3, w.kCu, "elapsed >=49 ticks >= 3000ms → cu3")
    }

    @Test fun `pause edge does NOT skip the logo dwells — unskippable`() {
        // proven (k.java:4003-4054): R() cases 2/3 advance only on the
        // 3000ms `du` timer — no input check exists in any arm. The
        // port's earlier pause-skip was a non-verbatim nicety, removed.
        val w = world()
        w.stateL(0)
        w.tick(emptyList()); w.tick(emptyList())      // cu2
        w.pad.queuePress(Pad.M_PAUSE)
        w.tick(emptyList())
        assertEquals(2, w.kCu, "splash dwell ignores pause")
        repeat(49) { w.tick(emptyList()) }            // ~3000ms elapse
        assertEquals(3, w.kCu, "timer alone advances the dwell")
    }

    @Test fun `loading screen ignores pause then lands on jc23 prompt`() {
        val w = world()
        w.stateL(0)
        w.tick(emptyList()); w.tick(emptyList())      // cu2
        repeat(49) { w.tick(emptyList()) }            // cu2 → cu3
        repeat(49) { w.tick(emptyList()) }            // cu3 → cu4
        w.tick(emptyList()); w.tick(emptyList())      // cu4→5→6 (5 runs 6's check)
        assertEquals(6, w.kCu)
        w.pad.queuePress(Pad.M_PAUSE)                 // no skip on cu6
        w.tick(emptyList())
        assertEquals(6, w.kCu, "case 6 has no pause skip")
        repeat(76) { w.tick(emptyList()) }            // elapsed ..80
        assertEquals(6, w.kCu, "elapsed <81 ticks < 5000ms")
        w.tick(emptyList())                           // elapsed hits 81
        assertEquals(23, w.jC, "l(23) — sound prompt")
        assertEquals(19, w.kEc)
        assertEquals(0, w.kCu, "l() resets cu — proven k.java:1644")
    }

    @Test fun `full boot chain reaches title and main menu`() {
        val w = world()
        w.stateL(0)
        repeat(180) { w.tick(emptyList()) }           // boot: 2+48+48+2+80 ticks
        assertEquals(23, w.jC)
        w.kBw = 0                                     // YES
        w.pad.queuePress(327712)
        w.tick(emptyList())
        assertEquals(18, w.jC, "confirm → l(18) title")
        w.pad.queuePress(Pad.M_CONTEXT)
        w.tick(emptyList())
        assertTrue(w.kCS)
        w.tick(emptyList())
        assertEquals(2, w.jC, "title → main menu")
    }
}

