        val p = w.player
        p.setAnim(6); p.setPositionPx(e.ak, e.al); p.refreshBoxes()
        p.av = e.ak < p.ak
        e.X[0] = p.W[0]; e.X[2] = p.W[2]
        e.X[1] = p.W[1]; e.X[3] = p.W[3]
