            if (p.al + 120 < w.kP) w.kP = p.al + 120
            w.tick(emptyList())
            if (p.ak > maxAk) maxAk = p.ak
            if (p.ak == lastAk && p.aZ) stall++ else { stall = 0; lastAk = p.ak }
            if (p.S != prevS || t % 40 == 0 || stall > 100) {
