            if (w.jC == 21) { if (t % 40 == 0) { w.pad.e(Pad.M_CONTEXT); w.pad.releaseFlush() }; continue }
            if (w.jC == 12 || w.jC == 13) {
                println("J FAIL t=$t @(${p.ak},${p.al}) S${p.S} jC=${w.jC} maxAk=$maxAk")
                var guard = 0
