                !p.aZ && p.ag < 0 && p.al in 300..470 && p.ak in 6900..7050 -> Pad.M_TAP_L or Pad.M_UP
                !p.aZ && p.al in 240..460 && p.ak in 6790..6900 -> Pad.M_TAP_L or Pad.M_UP
                !p.aZ && p.al > 560 && p.ak in 6800..6920 -> Pad.M_TAP_L or Pad.M_UP
